'use strict';
/* Guide (English) — part 2: Narrative Devices, Narrative Techniques, Planning & Structure Methods, Narrative Styles & Genres.
   Same data format as the other parts (see apoio-a.js): SUPPORT.push({ key, name, kicker, intro, groups:[{ name, items:[...] }] }).
   Entry fields: n name · a other names · d description · u how to use · c cautions · x examples · t in this tool · s related entries.
   Strings use double quotes and typographic apostrophes/quotes so English text needs no escaping. */

/* ============ NARRATIVE DEVICES ============ */
SUPPORT.push({ key:"recursos", name:"Narrative Devices", kicker:"Device",
  intro:"The machinery that makes a plot work: what you put into the story, and in what order you reveal it, to create anticipation, surprise and meaning. Figures of speech work on the sentence; these devices work on the story itself — on time, on what the reader knows and when, on the engines of conflict and on the jobs characters do.",
  groups:[
  { name:"Time and order", items:[
    { n:"Flashback", a:"Analepsis · retrospection · backstory scene",
      d:"A move back in time: the narration interrupts the story’s present to tell something that happened earlier. It can be a full scene, a paragraph, or a single remembered sentence.",
      u:"Use it when the past becomes necessary to understand the present — ideally after the reader already wants to know. Enter and leave through a concrete trigger (a smell, an object, a phrase). In past-tense narration, slip in with two or three verbs in the past perfect (“She had been nineteen…”), then settle into the simple past; a past-perfect verb on the way out signals the return.",
      c:"A flashback in the first pages stalls the opening; if the past is more gripping than the present, perhaps the story should start there. Avoid “dream” or “mirror” devices that announce the flashback clumsily, and avoid flashbacks inside flashbacks unless the structure is the point.",
      x:["*Wuthering Heights*: almost the whole novel is Nelly Dean’s retrospective account to Lockwood.", "*Great Expectations* is narrated by an older Pip looking back on his youth.", "*The Godfather Part II* cuts between young Vito and the present of Michael.", "Eça de Queirós, *The Maias*: after presenting the family house in 1875, the narrator goes back to tell Afonso’s youth and Pedro’s tragedy."],
      t:"Each Scene has two positions: narrative order (where it is told, on the Narrative board, along the white line) and chronological order (when it happens, along its Story Arc’s colored line). A flashback is a Scene that sits late in narrative order but early in chronology.",
      s:["Flash-forward", "In medias res", "Nonlinear narrative", "Story and plot"] },
    { n:"Flash-forward", a:"Prolepsis · anticipation · prolepsis in a sentence",
      d:"A move forward in time: the narration reveals events that will only happen later.",
      u:"It swaps the question “what will happen?” for “how will it come to this?.” A single sentence can do it (“It was the last time she would see him”). Prophecies, dreams and omens are flash-forwards inside the story itself.",
      c:"Revealing too much drains tension from the scenes that follow; reveal the outcome, keep the path hidden.",
      x:["*One Hundred Years of Solitude* opens “many years later” with Colonel Aureliano Buendía facing the firing squad.", "*Chronicle of a Death Foretold* (García Márquez): the death is announced in the first sentence.", "Muriel Spark, *The Prime of Miss Jean Brodie*: the narrator casually tells us who will betray Miss Brodie, long before it happens.", "The witches’ prophecies in *Macbeth*."],
      s:["Flashback", "Foreshadowing", "Dramatic irony", "Story and plot"] },
    { n:"In medias res", a:"Starting in the middle · the opposite of starting “ab ovo”",
      d:"Opening with the action already under way and leaving the background for later. The opposite, beginning from the very beginning, is called *ab ovo* (“from the egg”), after Horace.",
      u:"Open on a scene with movement and a question, as close as possible to the inciting incident. Give only the context the reader cannot do without, and distribute the rest later, through flashbacks or dialogue.",
      c:"Pure action with no character the reader cares about is just noise; and jumping straight back into the past in chapter two can feel like a bait and switch.",
      x:["The *Iliad* opens in the tenth and final year of the war; the *Odyssey* with Odysseus already years away from home.", "Kafka, *The Metamorphosis*: Gregor Samsa wakes up already transformed.", "*Paradise Lost* opens with the rebel angels already fallen.", "Camões, *The Lusiads*: the fleet is already sailing the Indian Ocean when the poem begins."],
      s:["Flashback", "Inciting incident", "Late in, early out", "Exposition and incluing"] },
    { n:"Ticking clock", a:"Deadline · countdown · race against time",
      d:"A time limit known to the reader, after which something irreversible will happen.",
      u:"It gives urgency to any goal and forces characters to act — and to make mistakes. Make the deadline concrete (midnight, the wedding, the tide, the oxygen) and consider shortening it halfway through to tighten the screw.",
      c:"A clock that is ignored for chapters, or that is extended whenever the plot needs more time, stops ticking for the reader.",
      x:["Jules Verne, *Around the World in Eighty Days*.", "Cinderella’s midnight.", "*High Noon*: the train arrives at twelve; the TV series *24* runs in real time.", "*Chronicle of a Death Foretold*: the whole town knows the hour — except the victim."],
      s:["Stakes", "Suspense and surprise", "Pacing"] },
    { n:"Circular narrative", a:"Ring composition · bookending · framing image",
      d:"The ending returns to the starting point — the same place, image, sentence or situation — but with its meaning transformed by everything that has happened in between.",
      u:"Show the same image at the start and at the end: the difference between them measures the character’s arc. Or change nothing — and the return becomes a sentence of doom.",
      c:"If the return is only decorative (the same weather, the same café) and nothing has shifted, it feels like a trick rather than a meaning.",
      x:["*The Hobbit*, subtitled *There and Back Again*.", "Joyce, *Finnegans Wake*: the last sentence runs on into the first.", "*One Hundred Years of Solitude*: the ending fulfils what the parchments always contained.", "Fitzgerald’s *The Great Gatsby* ends where it began, with Nick and the green light, now understood."],
      s:["Frame narrative", "Character arc", "Story circle"] },
    { n:"Story and plot", a:"Fabula and syuzhet · story and discourse (Russian Formalists, E. M. Forster)",
      d:"Two layers of every narrative. The story (fabula) is the events in the order they happened; the plot (syuzhet) is how the text arranges and presents them — order, emphasis, omission, point of view. E. M. Forster put the difference in causal terms: “The king died and then the queen died” is a story; “the queen died of grief” makes it a plot.",
      u:"Plan the two separately: first establish what really happened, in sequence; then decide in which order, through whose eyes and at what speed the reader will learn it. Most structural problems are plot problems: the events are fine, the order of revelation is not.",
      c:"Confusing the two leads to novels that tell everything chronologically just because that is how the author worked it out, or to timelines that contradict themselves once the order is shuffled.",
      x:["A detective novel tells the story of the investigation (plot) in order to reveal the story of the crime (fabula).", "*Memento* tells its fabula backwards; *Pulp Fiction* reshuffles it into chapters."],
      t:"The tool keeps both layers: the white line follows narrative order (plot), and each Story Arc’s colored line follows chronological order (story). When the two lines cross, you are looking at a flashback or a flash-forward.",
      s:["Flashback", "Flash-forward", "Nonlinear narrative", "Crime fiction"] }
  ]},
  { name:"Information, suspense and revelation", items:[
    { n:"Foreshadowing", a:"Omen · hint · presentiment",
      d:"A discreet signal of what is to come: a detail, a line of dialogue, an image, a dream, a minor incident that rehearses the major one.",
      u:"Ideally it goes unnoticed on first reading and feels inevitable on the second. Hide it in a list, inside a comic scene or in the middle of action. Write the ending first, then go back and plant it.",
      c:"Too obvious spoils the surprise; absent, it makes the ending feel arbitrary. Heavy-handed foreshadowing (“Little did she know…”) has become a cliché.",
      x:["*Romeo and Juliet*: the Prologue’s “star-cross’d lovers” and Juliet’s vision of Romeo “as one dead in the bottom of a tomb.”", "Steinbeck, *Of Mice and Men*: the shooting of Candy’s old dog rehearses the ending.", "*Jane Eyre*: the chestnut tree split by lightning the night Rochester proposes.", "Almeida Garrett, *Brother Luís de Sousa*: Telmo’s forebodings, the burning portrait, the ill-omened Friday."],
      t:"Attach one Note to both Scenes — the one that plants and the one that pays off — so you never lose sight of a piece of foreshadowing.",
      s:["Setup and payoff", "Chekhov’s gun", "Flash-forward", "Red herring"] },
    { n:"Chekhov’s gun", a:"The principle of narrative economy",
      d:"A principle of economy: everything the story puts in the spotlight should have a function. In Chekhov’s own formulation, if a rifle hangs on the wall in the first act, it must go off later.",
      u:"Read it both ways: cut what will not be used — and introduce well in advance everything that will be decisive at the end (the object, the skill, the weakness).",
      c:"It does not mean every detail must be a clue: settings need texture. It applies to what the text underlines.",
      x:["In Chekhov’s *Uncle Vanya*, the pistol goes off — and misses.", "The Time-Turner in *Harry Potter and the Prisoner of Azkaban*: shown as a curiosity, decisive later.", "*Back to the Future Part III*: the stove door under Marty’s poncho, set up earlier in a film playing on TV in Part II."],
      s:["Setup and payoff", "Foreshadowing", "Deus ex machina"] },
    { n:"Setup and payoff", a:"Plant and payoff · promise and fulfilment",
      d:"A pair of moments: something is established early (an object, a line, a rule, a promise) and later returns with consequences. It is the general mechanism of which foreshadowing and Chekhov’s gun are special cases.",
      u:"Plant anything essential three times, in different contexts; pay it off when the reader has almost forgotten it. Every promise made to the reader (a mystery, a threat, a postponed kiss) is a debt that must be paid.",
      c:"Payoffs without setups feel like cheating; setups without payoffs feel like loose threads.",
      x:["*Back to the Future*: the flyer about the lightning strike on the clock tower.", "*Ghostbusters*: “Don’t cross the streams.”", "In *Harry Potter*, the scar, the snake, the locket: everything comes back."],
      t:"Link the same Reference or Note to the setup Scene and the payoff Scene.",
      s:["Chekhov’s gun", "Foreshadowing", "Layered revision", "Motif"] },
    { n:"Red herring", a:"False clue · misdirection",
      d:"An element that deliberately draws the reader’s attention and suspicion in the wrong direction. The term comes from the strong-smelling smoked fish supposedly used to throw hounds off a scent.",
      u:"It must be plausible and have its own explanation at the end (the suspect was hiding something else). The best red herring hides the real clue, presented at the same moment and with less emphasis.",
      c:"If it is never explained, it is a loose end; if there are only false clues, the reader feels tricked.",
      x:["Snape in *Harry Potter and the Philosopher’s Stone*.", "Agatha Christie, *And Then There Were None* — whose own nursery rhyme mentions a red herring.", "Conan Doyle, *The Hound of the Baskervilles*: the escaped convict on the moor."],
      s:["Foreshadowing", "Plot twist", "Unreliable narrator", "Crime fiction"] },
    { n:"Suspense and surprise", a:"The bomb under the table (Hitchcock)",
      d:"Surprise: the reader does not know what is coming and is caught off guard — fifteen seconds of shock. Suspense: the reader knows there is a bomb under the table and the characters do not — fifteen minutes of anxiety. The distinction is Alfred Hitchcock’s, in his conversations with François Truffaut.",
      u:"To build suspense, give the reader information instead of hiding it, keep both outcomes possible, and delay the resolution. Suspense requires that the reader care about whoever is at risk.",
      c:"A string of surprises becomes tiring; suspense without resolution becomes irritating.",
      x:["*Psycho*: the surprise of the shower scene; afterwards, suspense whenever anyone approaches the house.", "*Jaws*: the audience sees the fin before the swimmers do.", "The opening of *Inglourious Basterds*: we know who is hiding under the floorboards."],
      s:["Dramatic irony", "Ticking clock", "Dramatic question", "Hook and cliffhanger"] },
    { n:"Dramatic irony", a:"The reader knows more than the character",
      d:"The reader knows something that one or more characters do not. Every line and gesture acquires a second meaning.",
      u:"A source of tension (the danger only we can see), comedy (the misunderstanding) and tragedy (the mistake only we recognize). It works especially well with several points of view: what one POV Character knows, the next one ignores.",
      c:"If the reader knows too much for too long and nothing happens with it, irony turns into impatience. Pay it off: the moment of discovery must come.",
      x:["Sophocles, *Oedipus the King*: Oedipus hunts for the murderer he himself is.", "*Romeo and Juliet*: we know Juliet is only sleeping.", "*Othello*: everyone on stage calls Iago “honest”; only we know.", "*Emma*: the reader sees long before Emma that Mr. Elton is courting her, not Harriet."],
      t:"With several Story Arcs and POV Characters, the Narrative board shows what each thread has already revealed at each point of narrative order.",
      s:["Suspense and surprise", "Irony", "Multiple narrators", "Recognition and reversal"] },
    { n:"Dramatic question", a:"Central question · story question",
      d:"The question the story raises at the beginning and answers only at the climax: will the hero succeed? Who did it? Will they end up together? Each scene also raises smaller questions of its own.",
      u:"State the central question in one sentence and check that the climax answers it. To keep the pages turning, open a new question before closing the previous one.",
      c:"A climax that answers a different question from the one the opening posed (the thriller that ends as a love story) leaves the reader feeling short-changed.",
      x:["“Who killed Roger Ackroyd?”", "“Will Odysseus get home to Ithaca — and what will he find there?”", "“Will Elizabeth and Darcy overcome pride and prejudice?”"],
      s:["Hook and cliffhanger", "Climax", "Premise and logline", "MICE quotient"] },
    { n:"Hook and cliffhanger", a:"Opening hook · chapter-ending hook · page-turner",
      d:"Whatever grabs readers and compels them to continue. At the opening: an intriguing sentence, voice or situation. At the end of a chapter (the cliffhanger): a cut at the moment of greatest tension, a revelation or a new question. The word comes from serial fiction that left heroes literally hanging from cliffs.",
      u:"End the chapter before the answer, not after. Vary the types (danger, revelation, decision, someone’s arrival). With several threads, switching to another thread right after a cliffhanger doubles its effect.",
      c:"If every chapter ends with someone fainting, readers see the trick; and a cliffhanger resolved with a shrug (“it was only the cat”) feels like a con.",
      x:["Scheherazade in *One Thousand and One Nights*: breaking off at dawn to survive one more day.", "Nineteenth-century serial novels — Dickens, Dumas, Wilkie Collins — lived on “to be continued”; the maxim “make ’em laugh, make ’em cry, make ’em wait” is attributed to Collins or to Charles Reade.", "Dan Brown, *The Da Vinci Code*: short chapters, nearly all ending on a hook."],
      s:["Short chapters and cliffhangers", "Suspense and surprise", "Crosscutting", "Dramatic question"] },
    { n:"Plot twist", a:"Twist · reversal of understanding",
      d:"A sudden, unexpected change in the direction of the story or in the way we understand it.",
      u:"A good twist is both surprising and inevitable: it surprises in the moment and, looking back, everything was there. It forces a rereading of what came before and raises the stakes. Build it from the ending backwards and plant the clues in plain sight.",
      c:"A twist that contradicts what has been shown, or cancels what the reader lived through (“it was all a dream”), is felt as a betrayal.",
      x:["Agatha Christie, *The Murder of Roger Ackroyd*.", "Gillian Flynn, *Gone Girl*: the turn at the midpoint.", "*The Sixth Sense*; *Fight Club*; *The Others*.", "*The Empire Strikes Back*: Vader’s revelation about Luke’s father."],
      s:["Recognition and reversal", "Foreshadowing", "Red herring", "Unreliable narrator", "Midpoint"] },
    { n:"Recognition and reversal", a:"Anagnorisis and peripeteia (Aristotle)",
      d:"Peripeteia: a sudden reversal of fortune, from happiness to misery or the other way round. Anagnorisis: the passage from ignorance to knowledge — a character discovers an identity or a truth. According to Aristotle’s *Poetics*, the effect is strongest when the two coincide.",
      u:"Make the revelation an act that changes everything: recognition should force a decision. It can concern someone else (who she really is) or oneself (who I am, what I have done).",
      c:"A recognition that changes nothing — the character learns the truth and carries on as before — wastes the most powerful moment a plot can offer.",
      x:["*Oedipus the King*: the messenger who comes to reassure Oedipus reveals his origins — and destroys him.", "Odysseus recognized by his old nurse through the scar on his leg.", "*King Lear*: Lear recognizes Cordelia, and his own folly, too late.", "*The Maias*: the revelation that Maria Eduarda is Carlos’s sister."],
      s:["Plot twist", "Dramatic irony", "Climax", "Tragic flaw", "Epiphany"] },
    { n:"Epiphany", a:"Moment of revelation (James Joyce)",
      d:"A sudden moment of insight in which a character — or the reader — perceives the true nature of a situation, a person or themselves. Joyce borrowed the religious term and made it the structural hinge of the modern short story in *Dubliners*.",
      u:"Prepare it with concrete, ordinary details, then let a small trigger (a song, a glance, a sentence overheard) crystallize what has been accumulating. Render the moment through image and sensation rather than stating the lesson.",
      c:"An epiphany spelled out as a moral (“And then he understood that…”) loses its force. It must be earned by the whole story, not announced in the last line.",
      x:["Joyce, “Araby”: the boy at the closing bazaar sees himself as a creature driven by vanity.", "Joyce, “The Dead”: Gabriel’s realization as the snow falls “faintly” over Ireland.", "Katherine Mansfield, “Bliss”: Bertha sees her husband with her friend."],
      s:["Recognition and reversal", "Short story", "Character arc", "Modernism"] }
  ]},
  { name:"Plot engines", items:[
    { n:"Inciting incident", a:"Catalyst · call to adventure · trigger",
      d:"The event that breaks the initial equilibrium and sets the story in motion: without it, the character’s life would carry on unchanged.",
      u:"It should happen early, on stage (as a scene, not a summary), strike the protagonist directly and raise the dramatic question. It can be an opportunity, a loss, a meeting, a letter, a corpse.",
      c:"Delaying it for a hundred pages of “setup” is the classic slow opening; equally, an incident that happens to a side character and only grazes the protagonist rarely carries a whole book.",
      x:["*Pride and Prejudice*: a rich young man, Mr. Bingley, takes Netherfield Park.", "The Hogwarts letter.", "*The Hunger Games*: Katniss volunteers in her sister’s place.", "*Jaws*: the first shark attack."],
      s:["Three-act structure", "Dramatic question", "Point of no return", "In medias res"] },
    { n:"Stakes", a:"What’s at stake · raising the stakes",
      d:"What the character gains by succeeding and, above all, what they lose by failing.",
      u:"Make them clear, personal and rising. External stakes (life, the kingdom, a job) weigh more when tied to internal ones (identity, love, guilt). Show early what could be lost, so the reader grows attached to it.",
      c:"“The end of the world” is an abstract stake; the death of one person we know weighs more than the loss of a planet.",
      x:["*The Hunger Games*: her own life — and her sister’s.", "*The Lord of the Rings*: Middle-earth, but also the Shire and Frodo’s soul.", "Kazuo Ishiguro, *The Remains of the Day*: only a wasted life — and that is enough."],
      s:["Ticking clock", "Dilemma", "Obstacles and complications"] },
    { n:"Obstacles and complications", a:"Conflict · escalation · rising action",
      d:"Everything that opposes the character’s desire: an antagonist, the environment, society, nature, fate — or the character’s own self. A complication is an obstacle that not only blocks but worsens or alters the situation.",
      u:"No opposition, no story. Make obstacles grow in difficulty and vary in kind (external, relational, internal). The best obstacle grows out of the character’s own plan or out of someone else’s legitimate desire.",
      c:"Obstacles that are all of the same kind (another fight, another locked door) feel repetitive; obstacles removed by luck feel cheap.",
      x:["The classic types of conflict: character vs character (*Les Misérables*: Valjean and Javert), vs society (*Nineteen Eighty-Four*), vs nature (*The Old Man and the Sea*), vs self (*Crime and Punishment*), vs fate (*Oedipus the King*); modern lists add vs technology and vs the supernatural."],
      s:["Try-fail cycles", "Antagonist", "Dilemma", "Fichtean curve"] },
    { n:"Dilemma", a:"Impossible choice · Sophie’s choice",
      d:"A choice between two incompatible options, both costly: two goods that exclude each other, or two unavoidable evils.",
      u:"Characters reveal themselves in choices made under pressure. Put the dilemma at the climax, and make the decision cost something we know and love.",
      c:"If one option is clearly better, it is not a dilemma — it is just an obstacle.",
      x:["William Styron, *Sophie’s Choice*.", "Sophocles, *Antigone*: obey the law of the city or bury her brother.", "E. M. Forster’s famous line on choosing between betraying one’s country and one’s friend.", "Frodo at the Crack of Doom."],
      s:["Stakes", "Climax", "Character arc", "Five commandments of storytelling"] },
    { n:"MacGuffin", a:"Term popularized by Alfred Hitchcock",
      d:"The object or goal that all the characters pursue and that sets the plot in motion, but whose exact nature hardly matters to the audience.",
      u:"It gives characters a reason to cross paths and collide. The interest lies in what they do to obtain it. You gain a great deal by also giving it symbolic or emotional value.",
      c:"If the reader is invited to care about what the MacGuffin is and never finds out, the vagueness reads as evasion rather than design.",
      x:["The statuette in Dashiell Hammett’s *The Maltese Falcon*.", "The glowing briefcase in *Pulp Fiction*, whose contents we never see.", "The Death Star plans in *Star Wars*.", "The Holy Grail in Arthurian romance."],
      s:["Dramatic question", "Symbol", "Stakes"] },
    { n:"Point of no return", a:"Crossing the threshold · first plot point · break into Act Two",
      d:"The moment the character makes a decision, or suffers an event, that makes a return to the old life impossible. It usually marks the entry into the second act.",
      u:"It should be a choice (even a forced one), not an accident. Burn the bridge: the house burns down, the secret is told, the ship sails.",
      c:"A protagonist who can simply go home at any moment, and the reader knows it, drains the middle of the book of urgency.",
      x:["Bilbo runs out of his front door without a pocket handkerchief.", "Raskolnikov commits the murder.", "*The Matrix*: Neo takes the red pill.", "Julius Caesar crossing the Rubicon gave the idea its proverbial name."],
      s:["Inciting incident", "Three-act structure", "Hero’s journey"] },
    { n:"Midpoint", a:"Midpoint reversal · central turn",
      d:"The event halfway through the story that changes the rules of the game: a revelation, a false victory or a false defeat that moves the protagonist from reacting to acting.",
      u:"It fights the “sagging middle” of novels. Raise the stakes, reveal something that changes the meaning of the goal, or grant a victory that comes with a price.",
      c:"A midpoint that is just another event of the same weight as the ones before it leaves the second act flat.",
      x:["*Gone Girl*: the switch of narrator halfway through.", "*Pride and Prejudice*: Darcy’s first proposal and the letter that follows it.", "*Titanic*: the iceberg."],
      s:["Three-act structure", "Save the Cat", "Plot twist"] },
    { n:"All is lost", a:"Dark night of the soul · crisis · lowest point",
      d:"The lowest point before the climax: the plan has failed, the mentor has died, the allies have left, and the character must face their flaw.",
      u:"The defeat should be the consequence of the character’s own mistakes and should force them to change (or refuse to change, in tragedy). The deeper the pit, the greater the effect of the climax.",
      c:"A low point caused purely by outside bad luck teaches the character nothing; and a recovery that takes one paragraph cheapens it.",
      x:["Gandalf falls in Moria; Obi-Wan dies; Dumbledore dies.", "Elizabeth, convinced that Lydia’s elopement has separated her from Darcy for ever.", "*Jane Eyre*: Jane flees Thornfield and nearly dies on the moors."],
      s:["Climax", "Save the Cat", "Character arc", "Mentor"] },
    { n:"Climax", a:"Showdown · decisive confrontation",
      d:"The moment of greatest tension, in which the central conflict is decided and the dramatic question is answered.",
      u:"The protagonist must be present and decide through their own actions, using what they have learned. The external climax (the battle) and the internal one (the choice) should coincide. Everything that was planted is harvested here.",
      c:"A climax resolved by another character, by chance or by a newly invented rule robs the protagonist of the victory.",
      x:["The destruction of the Ring at Mount Doom.", "The final duel in *Hamlet*.", "Darcy’s second proposal.", "*Jane Eyre*: Jane hears Rochester’s voice calling and chooses to return."],
      s:["Dilemma", "Resolution", "Deus ex machina", "Freytag’s pyramid"] },
    { n:"Resolution", a:"Dénouement · falling action · epilogue",
      d:"What comes after the climax: consequences, threads tied off, the new equilibrium. An epilogue is a resolution separated from the main action by a leap in time.",
      u:"Show the world changed and the cost of victory. Be brief: the tension is over. Open endings are resolutions too — they answer the central question and leave what comes next undecided.",
      c:"Multiple false endings (the film that ends five times) and epilogues that tell us the fate of every minor character dissipate the final emotion.",
      x:["The Scouring of the Shire and the Grey Havens in *The Lord of the Rings*.", "*Jane Eyre*: “Reader, I married him.”", "Open endings: *The Great Gatsby*; Cormac McCarthy’s *The Road*.", "*The Maias*: the last chapter, ten years later."],
      s:["Climax", "Circular narrative", "Freytag’s pyramid"] },
    { n:"Deus ex machina", a:"“God from the machine”",
      d:"A sudden, external solution to a hopeless problem: a character, force or coincidence that was never prepared for and fixes everything. The name comes from Greek theater, where a god was lowered onto the stage by a crane.",
      u:"As a rule, avoid it: the solution should arise from the characters and from what has been planted. Coincidence may get characters into trouble; it should not get them out. It is used deliberately in comedy, satire and parody.",
      c:"Watch for its modern disguises: the sudden new power, the convenient amnesia, the cavalry that arrives because the author needed it.",
      x:["Euripides, *Medea*: the chariot of the Sun carries Medea away.", "The eagles in *The Hobbit* and *The Lord of the Rings* — an eternal debate.", "The king’s intervention at the end of Molière’s *Tartuffe*.", "H. G. Wells, *The War of the Worlds*: the bacteria — though here the twist is the point."],
      s:["Chekhov’s gun", "Setup and payoff", "Climax", "Verisimilitude"] }
  ]},
  { name:"Characters as devices", items:[
    { n:"Character arc", a:"Positive, negative and flat arcs",
      d:"The inner transformation of a character over the course of the story. Positive arc: overcoming a flaw or a false belief. Negative arc: giving in to it (fall, corruption, disillusionment). Flat arc: the character does not change — they change the world around them.",
      u:"Define what the character wants (external goal), what they need (inner truth) and the lie they believe. The plot is the series of pressures that forces them to choose between the two.",
      c:"A change that happens off stage, or all at once in the last chapter, is not an arc; show the intermediate steps and the backsliding.",
      x:["Positive: Scrooge in *A Christmas Carol*; Elizabeth Bennet.", "Negative: Macbeth; Michael Corleone; Walter White.", "Flat: Sherlock Holmes; James Bond; Paddington."],
      t:"The Character details panel shows the Scenes they appear in, in the order they are told: that is the skeleton of the arc.",
      s:["Want and need", "Tragic flaw", "All is lost", "Hero’s journey"] },
    { n:"Tragic flaw", a:"Hamartia · wound and lie",
      d:"The error of judgment or trait of character that brings the hero down (in tragedy) or that they must overcome (in other stories). Contemporary craft books speak of the “wound” (what happened to the character) and the “lie” (what they came to believe because of it).",
      u:"The flaw works best as the reverse side of a virtue (courage that is recklessness, loyalty that is blindness) and should cause the problems of the plot.",
      c:"A flaw that never costs the character anything is decoration; and a cute flaw (“she’s too clumsy”) is not a flaw at all.",
      x:["Oedipus’s hubris.", "Macbeth’s ambition; Othello’s jealousy; Hamlet’s indecision.", "Darcy’s pride and Elizabeth’s prejudice.", "Victor Frankenstein’s ambition and his refusal of responsibility."],
      s:["Character arc", "Recognition and reversal", "Want and need"] },
    { n:"Antagonist", a:"Opponent · villain · opposing force",
      d:"The force that opposes the protagonist. It need not be a villain: it can be a rival with a legitimate goal, an institution, nature, or the protagonist themself.",
      u:"The best antagonist wants something understandable, is stronger than the hero at the start, and attacks precisely the hero’s weakness. Every antagonist is the hero of their own story.",
      c:"The villain who is evil “just because” is not frightening.",
      x:["Javert in *Les Misérables*: the law without mercy.", "Iago in *Othello*.", "Big Brother in *Nineteen Eighty-Four*.", "The whale — or Ahab’s obsession — in *Moby-Dick*."],
      s:["Obstacles and complications", "Foil", "Antihero"] },
    { n:"Antihero", a:"Protagonist without heroic virtues",
      d:"A protagonist lacking the traditional qualities of the hero: cowardly, selfish, amoral, a failure or simply ordinary.",
      u:"Readers need not like them; they need to understand them and be unable to look away. Give them competence, a code, humor or a vulnerability.",
      c:"Nastiness is not depth: an antihero who is only unpleasant, with no inner contradiction, is just tiresome company.",
      x:["Don Quixote; Lazarillo de Tormes and the picaros.", "Raskolnikov in *Crime and Punishment*.", "Meursault in Camus’s *The Stranger*.", "Patricia Highsmith’s Tom Ripley; Thackeray’s Becky Sharp."],
      s:["Antagonist", "Unreliable narrator", "Character arc", "Picaresque novel"] },
    { n:"Foil", a:"Contrast character",
      d:"A character whose traits contrast with another’s (usually the protagonist’s), making them more visible.",
      u:"Give the pair the same situation and opposite responses. The foil shows what the protagonist could have been.",
      c:"A foil that is merely the protagonist’s opposite in every respect becomes a cardboard cut-out; the contrast is stronger when the two also share something.",
      x:["Don Quixote and Sancho Panza.", "Sherlock Holmes and Watson.", "Harry Potter and Draco Malfoy.", "Laertes and Hamlet: two sons avenging a father, one rash, one hesitant."],
      s:["Antithesis", "Subplot", "Confidant"] },
    { n:"Confidant", a:"Sidekick · sounding board",
      d:"A character to whom the protagonist confides thoughts and plans — and, through them, to the reader.",
      u:"It turns monologue into dialogue and exposition into scene. Give the confidant a life and opinions of their own (disagreeing is more useful than nodding).",
      c:"A confidant who only asks questions is a microphone on legs.",
      x:["Horatio in *Hamlet*.", "Watson.", "Nick Carraway, Gatsby’s confidant and the reader’s.", "Eça de Queirós, *Cousin Bazilio*: the maid Juliana knows the secret and is no ally — which is why the novel works."],
      s:["Foil", "Exposition and incluing", "Direct speech"] },
    { n:"Mentor", a:"Wise old man / woman · teacher",
      d:"An older or wiser figure who prepares the hero, gives them a gift (knowledge, an object, confidence) and often disappears before the final ordeal.",
      u:"The mentor has to leave the stage so the hero can prove what they have learned. Give mentors flaws, secrets or a past that complicates the lesson.",
      c:"An infallible mentor who explains everything removes the hero’s need to discover anything.",
      x:["Gandalf; Dumbledore; Obi-Wan Kenobi.", "Mentor (Athena in disguise) in the *Odyssey* — the origin of the word.", "Miss Havisham as a monstrous anti-mentor in *Great Expectations*."],
      s:["Hero’s journey", "All is lost", "Archetype"] },
    { n:"Stock character", a:"Type · stereotype · commedia types",
      d:"A character who represents a class, profession or vice through a few fixed, instantly recognizable traits: the miser, the braggart soldier, the jealous husband, the hard-boiled detective, the manic pixie dream girl.",
      u:"Stock characters are useful: recognized at once, ideal for satire and for populating the background. To refresh one, keep the outline and add one specific, contradictory detail.",
      c:"Stock characters in leading roles make a book predictable; and many stock types carry prejudices about class, gender or ethnicity that need to be questioned.",
      x:["The medieval morality play: Everyman, Good Deeds, Fellowship.", "Restoration comedy: Sir Fopling Flutter, Lady Wishfort.", "Dickens: Mr. Micawber, forever waiting for something to “turn up.”", "Gil Vicente’s nobleman, usurer and friar in the Portuguese *Barcas* plays."],
      s:["Flat and round characters", "Archetype", "Direct and indirect characterization", "Idiolect and speech patterns"] },
    { n:"Flat and round characters", a:"E. M. Forster, *Aspects of the Novel* (1927)",
      d:"Forster’s distinction: flat characters are built around a single idea or quality and do not change; round characters are complex and capable of surprising in a convincing way — his test for roundness.",
      u:"Flat characters keep a big cast manageable and are often the most memorable comic figures. Main characters should be round: give them a contradiction, a secret and a capacity to act against expectation.",
      c:"Flat does not mean bad — Forster himself defended them. The mistake is a flat protagonist, or a round character whose surprises are merely inconsistent.",
      x:["Flat: Mrs. Micawber, whose whole being is “I never will desert Mr. Micawber.”", "Round: Emma Woodhouse; Anna Karenina; Leopold Bloom."],
      s:["Stock character", "Character arc", "Direct and indirect characterization"] },
    { n:"Archetype", a:"Jungian archetypes · Vogler’s character functions",
      d:"A recurring role or pattern of character found across myths and stories. Christopher Vogler, after Jung and Campbell, lists functions such as hero, mentor, threshold guardian, herald, shapeshifter, shadow, ally and trickster. One character can wear several masks, and change them.",
      u:"Think of archetypes as jobs that need doing in the story rather than as personalities: who tests the hero at the threshold? Who brings the call? Who keeps the reader unsure of their loyalty (shapeshifter)?",
      c:"An archetype is a skeleton, not a character: without specific desires, history and voice it collapses into a stereotype.",
      x:["Threshold guardian: the troll on the bridge; the bouncer at the club.", "Shapeshifter: Severus Snape; Mrs Danvers in *Rebecca*.", "Trickster: Loki; Puck in *A Midsummer Night’s Dream*; Bugs Bunny."],
      s:["Hero’s journey", "Mentor", "Stock character"] },
    { n:"Subplot", a:"B-story · secondary plot",
      d:"A line of action running parallel to the main one, with its own characters and conflict.",
      u:"A good subplot mirrors, contrasts with or complicates the main plot — it treats the same theme from another angle — and crosses it at a decisive moment. It gives the book room to breathe and somewhere to cut to after a cliffhanger.",
      c:"If it can be removed without changing anything in the main plot, it belongs to another book.",
      x:["*Anna Karenina*: Levin and Kitty set against Anna and Vronsky.", "*King Lear*: Gloucester and his sons mirror Lear and his daughters.", "*Middlemarch*: four interlocking plots in one provincial town."],
      t:"Each subplot can be its own Story Arc with its own lane; Branches and convergences show where it splits from the main arc and where it rejoins it.",
      s:["Crosscutting", "Interlacing", "Foil", "Save the Cat"] }
  ]}
]});

/* ============ NARRATIVE TECHNIQUES ============ */
SUPPORT.push({ key:"tecnicas", name:"Narrative Techniques", kicker:"Technique",
  intro:"The craft of putting the story on the page: how a scene is built, how speed is managed, how the parts are arranged, how we get inside characters’ heads, and what game is played with the reader. If narrative devices are what happens in the story, techniques are the way of telling it.",
  groups:[
  { name:"Scene and pace", items:[
    { n:"Show, don’t tell", a:"Dramatize rather than report",
      d:"Instead of stating a feeling or a quality (“she was nervous,” “he was generous”), present the actions, gestures, words and details that let readers conclude it for themselves.",
      u:"Show what matters — emotions, turning points, relationships — and let the reader do the sum. A good test: could a camera film this, or an actor play it? Replace abstract adjectives with one precise action.",
      c:"It is not an absolute law: telling is indispensable for summarizing, linking scenes and giving context. Showing everything makes a book endless. And “showing” an emotion through clichéd body language (pounding hearts, released breaths) is still telling in disguise.",
      x:["Telling: “Rob was furious.”", "Showing: “Rob set his glass down so carefully that the whole table went quiet.”", "Telling: “It was a poor house.” / Showing: “The kitchen lino had worn through to the concrete in front of the stove.”"],
      s:["Scene and summary", "Telling detail", "Objective correlative", "Subtext", "Direct and indirect characterization"] },
    { n:"Scene and summary", a:"The speeds of narration (Genette): scene · summary · ellipsis · pause",
      d:"Scene: the time of telling approaches the time of the story — action and dialogue, moment by moment. Summary: a few lines cover days or years. With ellipsis (time skipped) and pause (action suspended for description or reflection), these are the four speeds available to a narrator, as described by Gérard Genette.",
      u:"Dramatize in scene whatever changes something — decisions, confrontations, revelations; put routine, travel and transitions into summary. Alternating the four speeds is what gives a book its rhythm.",
      c:"The classic mistake is to summarize the decisive moments and dramatize the trivial ones.",
      x:["Summary: “For three years they wrote to each other every week.”", "Scene: the letter that stops arriving — and what she does that morning.", "*The Maias*: decades of family history in summary; then two years in long scenes."],
      t:"A Scene on the board should correspond to an actual scene; what is summary can live in the Chapter’s synopsis or in a Note.",
      s:["Time skip", "Descriptive pause and digression", "Pacing", "Show, don’t tell"] },
    { n:"Scene and sequel", a:"Dwight V. Swain, *Techniques of the Selling Writer* (1965)",
      d:"A pair that repeats throughout a book. The scene (action) has goal, conflict and disaster (the character fails to get what they wanted, or gets it at a cost). The sequel (reaction) has reaction (emotion), dilemma (what now?) and decision — which provides the goal of the next scene.",
      u:"Check every scene: what does the character want, who or what stops them, and how do they end up worse off than they began? Shorten sequels to speed up; lengthen them to deepen character.",
      c:"Sequels that repeat in thought what the scene has just shown are dead weight; skipping sequels altogether gives breathless books whose characters never seem to feel anything.",
      x:["Scene: Anna goes to ask for a loan (goal); the manager is her ex-brother-in-law (conflict); he refuses and threatens to tell everything (disaster).", "Sequel: Anna cries in the car (reaction); sell the house or call her brother? (dilemma); she calls her brother (decision → new scene)."],
      s:["Try-fail cycles", "Pacing", "Obstacles and complications"] },
    { n:"Try-fail cycles", a:"“Yes, but…” / “No, and furthermore…”",
      d:"Every attempt the character makes to solve the problem ends in one of two ways: it succeeds, but a new complication arises; or it fails, and things get worse. Plain “yes” and plain “no” are saved for the end.",
      u:"Ask of every scene: “Does the character get what they want?” and choose “yes, but” or “no, and.” It is the simplest way to guarantee escalation and stop the middle of a book from stalling. Many writers recommend at least two failed attempts before the success, so the success feels earned.",
      c:"If the failures are random and do not teach the character anything, the cycle becomes a treadmill.",
      x:["“Does Indiana Jones get the Ark? Yes, but the Nazis seal him in the Well of Souls. Does he get out? Yes, but the Ark is already on a truck…”", "“Does she get the safe open? No — and the alarm goes off.”"],
      s:["Scene and sequel", "Obstacles and complications", "Rule of three", "Fichtean curve"] },
    { n:"Late in, early out", a:"Arrive late, leave early (screenwriting maxim)",
      d:"Start each scene as close as possible to the moment that matters and end it as soon as that moment is complete — no arrivals, greetings, goodbyes or conclusions.",
      u:"In revision, try cutting the first and last paragraph of every scene. End on an image, a line or a question, not on an explanation.",
      c:"Cutting too hard can strip away the breathing space readers need to absorb a big moment; leave the occasional beat after a revelation.",
      x:["Instead of “He parked, climbed the stairs, rang the bell. ‘Hi, Martha…’” — start with: “‘How long have you known?’ Martha asked, without letting him in.”"],
      s:["Time skip", "In medias res", "Short chapters and cliffhangers"] },
    { n:"Time skip", a:"Narrative ellipsis · jump cut · section break",
      d:"Omitting a stretch of story time: the narration skips hours, days or years. It can be signalled (“Two years later”) or implicit (a line break).",
      u:"Skip everything the reader can guess. An ellipsis can also hide: leaving out the crucial moment (the crime, the night, the conversation) creates a gap the reader fills in — and that can be revealed later.",
      c:"Unsignalled skips that leave the reader unsure how much time has passed cause confusion; anchor the new moment quickly (season, age, a changed detail).",
      x:["Flaubert, *Sentimental Education*: “He traveled.” — and years go by.", "Virginia Woolf, *To the Lighthouse*: the middle section, “Time Passes,” crosses ten years, with major deaths reported in brackets.", "*2001: A Space Odyssey*: the bone becomes a spacecraft — millions of years in one cut."],
      s:["Scene and summary", "Ellipsis", "Paragraphing and white space", "Late in, early out"] },
    { n:"Descriptive pause and digression", a:"Pause · digression · aside",
      d:"Suspending the action to describe, comment or wander. In a digression, the narrator leaves the thread of the story to reflect, tell something else or address the reader.",
      u:"A pause brakes the story: use it after a peak of tension so the reader can breathe, or just before one to make them wait. A digression is a pleasure when the narrator’s voice is worth it for its own sake.",
      c:"A pause at the wrong moment kills suspense; readers in a hurry for plot will skip it.",
      x:["Sterne, *Tristram Shandy*: digression as the principle of composition.", "*Moby-Dick*: the chapters on whales and whaling.", "*Les Misérables*: Waterloo, the sewers of Paris.", "Fielding, *Tom Jones*: an essay opening each book."],
      s:["Description", "Scene and summary", "Pacing", "Intrusive narrator"] },
    { n:"Pacing", a:"Tempo · narrative speed",
      d:"The speed at which the story moves and at which the reader feels it move. It results from the proportion of scene to summary, the length of chapters, paragraphs and sentences, and the frequency of events.",
      u:"Speed up with short scenes, dialogue, short sentences, cuts and time skips; slow down with description, interiority, long sentences and sequels. Alternate tension and rest: a book that always runs is as tiring as one that never moves.",
      c:"“Fast-paced” is not automatically good: without slower passages, nothing has weight. Diagnose pace by scene function, not by word count.",
      x:["Thrillers: two-page chapters, alternating threads, a clock ticking.", "A useful paradox: at moments of maximum tension, slow down — narrate the decisive second in full detail, in “slow motion.”"],
      t:"On the Narrative board, the number of Scenes per Chapter and the alternation of Story Arcs give you a picture of the book’s pace.",
      s:["Scene and summary", "Sentence rhythm", "Short chapters and cliffhangers", "Scene and sequel"] },
    { n:"Short chapters and cliffhangers", a:"Page-turner architecture",
      d:"Dividing the narrative into brief units, each with its own small turn, ending in suspense.",
      u:"Each chapter should change something and leave a question open. Break off in the middle of the action and resume later. Chapter titles can also promise, mislead or joke.",
      c:"Overused, it feels mechanical. A long, calm chapter in the right place gives weight.",
      x:["Machado de Assis, *The Posthumous Memoirs of Brás Cubas*: chapters of a few lines, some made only of punctuation.", "James Patterson’s three-page chapters; *The Da Vinci Code*: more than a hundred chapters.", "Victorian serials: Dickens’s monthly numbers, each ending on a pull to the next."],
      t:"On the board, drag Scenes between Chapters to try out where the break falls.",
      s:["Hook and cliffhanger", "Crosscutting", "Pacing", "Paragraphing and white space"] }
  ]},
  { name:"Architecture of the narrative", items:[
    { n:"Frame narrative", a:"Frame story · story within a story · embedded narrative · narrative levels",
      d:"One narrative frames another, or several, told by characters of the first. Each story told inside another goes down one narrative level.",
      u:"The frame justifies the act of telling, creates a listener, and allows the inner story to be commented on and doubted. The meaning lies in the relationship between the levels (echo, contrast, explanation).",
      c:"If the frame has no tension of its own, it is only a delay.",
      x:["*One Thousand and One Nights*; Boccaccio, *The Decameron*; Chaucer, *The Canterbury Tales*.", "*Frankenstein*: Walton’s letters contain Victor’s account, which contains the creature’s.", "Conrad, *Heart of Darkness*: Marlow tells his tale aboard a yawl on the Thames.", "Henry James, *The Turn of the Screw*: a manuscript read aloud by a fireside."],
      s:["Mise en abyme", "Metalepsis", "First person — witness", "Circular narrative"] },
    { n:"Mise en abyme", a:"Story in the mirror · recursive image",
      d:"A work that contains a small-scale image of itself: a story, play, painting or book inside the story that reflects the whole.",
      u:"It condenses the theme, foreshadows the outcome or exposes a character. It should be felt as a reflection without being explained.",
      c:"When the mirror is pointed out by a character (“Isn’t that just like us?”), the effect evaporates.",
      x:["The play within the play in *Hamlet*, which stages the king’s crime.", "In Part Two of *Don Quixote*, the characters have read Part One.", "André Gide, *The Counterfeiters*: a novelist writes a novel called *The Counterfeiters*.", "Velázquez, *Las Meninas*, in painting."],
      s:["Frame narrative", "Metafiction", "Foreshadowing"] },
    { n:"Crosscutting", a:"Parallel editing · intercutting · alternating threads",
      d:"Alternating between two or more lines of action happening at the same time, in different places or with different characters.",
      u:"Cut from one line to another at a moment of tension; make the lines echo each other (the same gesture, the same word) and converge at the climax. The alternation can speed up as the end approaches.",
      c:"If one line is much weaker, readers will skip it; make sure each has its own question and its own progress.",
      x:["*The Lord of the Rings*: Frodo and Sam on one side, the war on the other.", "*War and Peace*: drawing rooms and battlefields.", "The baptism in *The Godfather*, intercut with the executions.", "George R. R. Martin, *A Song of Ice and Fire*."],
      t:"This is exactly what the Narrative board shows: each Story Arc in its own lane, and narrative order (the white line) alternating between them.",
      s:["Interlacing", "Subplot", "Hook and cliffhanger", "Multiple narrators"] },
    { n:"Interlacing", a:"Entrelacement · braided narrative · threads that split and converge",
      d:"Several narrative lines that advance in parallel, branch off from a common trunk and meet again. The technique comes from medieval French romance (*entrelacement*), where one knight’s adventure is suspended to follow another’s.",
      u:"Plan the points of contact: where one thread is born from another, where they cross, and what information passes at each crossing. A well-prepared convergence is one of the greatest rewards a reader can get.",
      c:"Too many threads with too few convergences turn a novel into a set of parallel books; readers lose track of who knows what.",
      x:["The Arthurian prose romances; Malory, *Le Morte d’Arthur*; Ariosto, *Orlando Furioso*.", "*The Lord of the Rings*: the Fellowship breaks up and reunites.", "David Mitchell, *Cloud Atlas*: six nested and linked stories.", "Mosaic films: *Short Cuts*, *Magnolia*, *Babel*."],
      t:"Branches (a Story Arc that diverges from another) and convergences (a Story Arc merging into another) exist precisely to draw this.",
      s:["Crosscutting", "Subplot", "Mosaic novel"] },
    { n:"Nonlinear narrative", a:"Anachrony · fragmented chronology",
      d:"The order in which events are told does not match the order in which they happened: backwards, forwards, in spirals or in shuffled fragments.",
      u:"Order the episodes by the logic of emotion or revelation, not by the calendar. Give the reader anchors (dates, ages, seasons, a haircut) to find their way.",
      c:"Disorder must produce a gain — suspense, irony, meaning — that straight chronology would not.",
      x:["Kurt Vonnegut, *Slaughterhouse-Five*: Billy Pilgrim has “come unstuck in time.”", "Christopher Nolan, *Memento*: told backwards.", "Martin Amis, *Time’s Arrow*: a life narrated in reverse.", "Juan Rulfo, *Pedro Páramo*; Audrey Niffenegger, *The Time Traveler’s Wife*."],
      t:"Compare narrative order and chronological order in each Story Arc’s details.",
      s:["Flashback", "Flash-forward", "Mosaic novel", "Story and plot"] },
    { n:"Mosaic novel", a:"Fragmentary novel · composite novel · short-story cycle",
      d:"The book is made of fragments, episodes, voices or loose documents that only form a picture as a whole.",
      u:"Each fragment must stand on its own and add a piece. Unity comes from a place, an event or a shared theme.",
      c:"Without a thread of progression, readers feel they are reading a pile of notes; let something accumulate or change from piece to piece.",
      x:["Sherwood Anderson, *Winesburg, Ohio*: one town in linked stories.", "Julio Cortázar, *Hopscotch*: chapters to be read in more than one order.", "Italo Calvino, *Invisible Cities*.", "Jennifer Egan, *A Visit from the Goon Squad*: one chapter is a slide presentation.", "Fernando Pessoa, *The Book of Disquiet*."],
      s:["Nonlinear narrative", "Epistolary", "Multiple narrators"] },
    { n:"Rashomon effect", a:"Contradictory versions",
      d:"The same event is told by several characters in incompatible versions, and the text does not decide which is true.",
      u:"Each version should reveal who is telling it — their interests, vanity, guilt. The reader becomes the judge.",
      c:"If one version is obviously the truth, the effect collapses into a simple puzzle; if none is grounded in anything, it becomes arbitrary.",
      x:["Kurosawa’s *Rashomon*, from stories by Akutagawa.", "Faulkner, *The Sound and the Fury* and *As I Lay Dying*.", "Lawrence Durrell, *The Alexandria Quartet*.", "Robert Browning, *The Ring and the Book*: a Roman murder told by ten speakers."],
      s:["Focalization", "Unreliable narrator", "Multiple narrators"] }
  ]},
  { name:"Interiority, character and dialogue", items:[
    { n:"Interior monologue", a:"Direct and indirect interior monologue",
      d:"The rendering of a character’s thoughts as they formulate them to themselves. It can be direct (first person, without narratorial mediation) or indirect (filtered through the narrator). Pushed to the extreme of free association, it becomes stream of consciousness.",
      u:"Use it at moments of decision, doubt or reaction — the sequels. Thought should have the character’s syntax and obsessions, and can contradict what they say aloud.",
      c:"Characters who think the obvious, or repeat what the scene has already shown, stall the pace. Avoid italicized thoughts on every page.",
      x:["Molly Bloom’s monologue at the end of Joyce’s *Ulysses*.", "Édouard Dujardin, *The Bays Are Sere* (*Les Lauriers sont coupés*, 1887), cited by Joyce as his model.", "Hamlet’s soliloquies — the stage equivalent."],
      s:["Stream of consciousness", "Free indirect speech", "Psychic distance", "Scene and sequel"] },
    { n:"Subtext", a:"What is not said",
      d:"What characters mean, feel or hide beneath what they actually say. Dialogue is the surface; subtext is the current.",
      u:"Have characters talk about something else — the weather, dinner, a piece of furniture — while they argue about what they cannot name. Give them opposing goals within the conversation. Gestures can contradict words.",
      c:"“On-the-nose” dialogue, in which everyone says exactly what they feel, sounds false.",
      x:["Hemingway, “Hills Like White Elephants”: a couple discuss an abortion without ever naming it.", "The plays of Chekhov and Harold Pinter.", "“‘It’s cold.’ ‘Do you want my coat?’ ‘No. I want to go home.’”"],
      s:["Iceberg theory", "Show, don’t tell", "Euphemism"] },
    { n:"Iceberg theory", a:"Theory of omission (Hemingway)",
      d:"Only a small part of the story appears on the surface of the text; the rest — the past, the motives, the emotion — stays submerged and supports what we see. Hemingway argued that a writer may omit what he knows well and the reader will still feel it.",
      u:"Know much more than you tell. Cut explanations, emotion adjectives and backstory; keep the facts, the gestures and the dialogue.",
      c:"You can only omit what you know: omitting out of ignorance leaves holes, not depth.",
      x:["Hemingway: in “Big Two-Hearted River” the war is never mentioned; in “Hills Like White Elephants” neither is the word “abortion.”", "The stories of Raymond Carver.", "Ishiguro, *The Remains of the Day*: the love the butler never names."],
      s:["Subtext", "Short sentences", "Show, don’t tell", "Worldbuilding", "Minimalism"] },
    { n:"Direct and indirect characterization", a:"Telling and showing character",
      d:"Direct: the narrator (or another character) says what the character is like. Indirect: the character is revealed by what they do, say, think, wear and own, by where they live and by the effect they have on others.",
      u:"Introduce with a direct stroke if you like, then confirm (or contradict) it through action. What a character does under pressure is worth more than anything said about them. A name, a house and an object also characterize.",
      c:"Long physical inventories on first appearance (“She had auburn hair, green eyes and…”) tell us little; pick one telling detail.",
      x:["Direct: “He was a miser.”", "Indirect: “He counted the coins twice before handing them over, and kept looking at them in the other man’s hand.”", "Dickens’s opening on Scrooge — “a squeezing, wrenching, grasping…” — is direct characterization raised to music."],
      t:"The Character details panel holds the description; the Scenes they appear in show where that description is put to the test.",
      s:["Show, don’t tell", "Telling detail", "Idiolect and speech patterns", "Stock character"] },
    { n:"Exposition and incluing", a:"Drip-feeding information · incluing (Jo Walton) · avoiding the info-dump",
      d:"Giving readers the information they need — backstory, the rules of the world, relationships — little by little, inside action and dialogue, instead of dumping it in a block. Fantasy and science-fiction writers call the technique “incluing,” a term coined by Jo Walton.",
      u:"Give each piece of information when it is needed, ideally as a weapon in a conflict (in an argument, in a lie). A newcomer to the setting justifies explanations. Create the curiosity first; answer it afterwards.",
      c:"Avoid the encyclopedia prologue and “As you know, Bob” dialogue, in which two characters tell each other what both already know.",
      x:["Bad: “‘As you know, brother, our father the king died ten years ago at the Battle of the Ford.’”", "Better: “‘Don’t talk to me about the Ford. You weren’t even there.’”", "Watson, Bilbo, Harry Potter: the newcomer to whom everything must be explained.", "The first line of *Nineteen Eighty-Four*: clocks striking thirteen tell us the world is different without a word of explanation."],
      s:["Worldbuilding", "In medias res", "Direct speech", "Confidant"] },
    { n:"Worldbuilding", a:"World creation · setting design",
      d:"The coherent invention of the story’s universe — geography, history, politics, economy, beliefs, technology or magic and their rules. It matters for fantasy and science fiction, but also for a historical novel or an invented village.",
      u:"Set rules and limits and keep to them: a magic system is defined by what it cannot do and by what it costs (the core of Brandon Sanderson’s “laws” of magic). Show the world through the characters’ everyday life (what they eat, fear, swear by).",
      c:"The world is an iceberg: nine-tenths stay in the author’s notes. “Worldbuilder’s disease” — endless invention that never becomes a story — is a real risk.",
      x:["Tolkien’s Middle-earth, with its own languages and mythology.", "Faulkner’s Yoknapatawpha County; García Márquez’s Macondo; Hardy’s Wessex.", "Frank Herbert, *Dune*: the ecology, religion and politics of a planet.", "Ursula K. Le Guin’s Earthsea."],
      t:"References and Notes are the place for the world’s “bible”: maps, timelines, rules, images — linked to the Books, Story Arcs and Sceneries they concern.",
      s:["Exposition and incluing", "Iceberg theory", "Verisimilitude", "Series bible", "Neologism"] }
  ]},
  { name:"Playing with the reader", items:[
    { n:"Verisimilitude", a:"Plausibility · willing suspension of disbelief (Coleridge)",
      d:"The quality of seeming true within the rules of the story itself. It is not realism: a dragon can be plausible and a real coincidence may not be. Readers agree to the “willing suspension of disbelief” (Coleridge’s phrase, 1817) as long as the text keeps the rules it has set.",
      u:"Establish the pact early — genre, tone, rules — and be consistent. Readers accept the impossible more easily than the improbable; concrete details buy their trust.",
      c:"“But it really happened like that!” is never an argument: fiction has to be more plausible than life.",
      x:["Aristotle: a plausible impossibility is preferable to an implausible possibility.", "*The Metamorphosis*: once the premise is accepted, everything else is rigorously logical.", "Mark Twain: truth is stranger than fiction, because fiction must stick to possibilities."],
      s:["Deus ex machina", "Worldbuilding", "Magical realism", "Telling detail"] },
    { n:"Metafiction", a:"Breaking the fourth wall · self-reflexive fiction",
      d:"Fiction that draws attention to its own fictionality: the narrator comments on the writing, speaks to the reader, discusses the characters as inventions, or the book takes itself as its subject.",
      u:"It creates complicity, humor and reflection on the act of storytelling. It can be an occasional wink or the architecture of the whole book.",
      c:"It reminds readers that none of it is real, which risks breaking the emotion; cleverness alone does not hold a reader for three hundred pages.",
      x:["Laurence Sterne, *Tristram Shandy*; Diderot, *Jacques the Fatalist*.", "Italo Calvino, *If on a Winter’s Night a Traveler*.", "John Fowles, *The French Lieutenant’s Woman*, with its alternative endings.", "Kurt Vonnegut appears in *Slaughterhouse-Five* and *Breakfast of Champions*; Ian McEwan, *Atonement*."],
      s:["Metalepsis", "Intrusive narrator", "Mise en abyme", "Apostrophe", "Intertextuality and allusion"] },
    { n:"Metalepsis", a:"Crossing narrative levels",
      d:"Transgressing the boundaries between narrative levels: the author enters the story, a character steps out of the book, the narrator interferes in what they narrate, the reader is pulled inside.",
      u:"It produces vertigo, humor or unease. It works best when the text has first established clear boundaries.",
      c:"Used as a cheap way out of a plot problem (the author steps in to fix it), it becomes a deus ex machina.",
      x:["Cortázar, “Continuity of Parks”: the reader of a novel is the victim of the crime he is reading about.", "Unamuno, *Mist*: the character goes to argue his fate with the author.", "Woody Allen, *The Purple Rose of Cairo*: the character walks out of the screen.", "Jasper Fforde, *The Eyre Affair*; Michael Ende, *The Neverending Story*."],
      s:["Metafiction", "Frame narrative", "Mise en abyme"] },
    { n:"Defamiliarization", a:"Ostranenie (Viktor Shklovsky) · making strange",
      d:"Presenting the familiar as if seen for the first time, so that the reader actually sees it instead of merely recognizing it. Shklovsky defined it in “Art as Device” (1917).",
      u:"Describe without using the thing’s usual name; adopt the point of view of a child, a foreigner, an animal or an alien; change the scale. It is the cure for cliché.",
      c:"Sustained too long, the strangeness becomes a puzzle the reader must decode at every line; use it to sharpen key moments.",
      x:["Tolstoy, “Kholstomer”: private property explained by a horse.", "Montesquieu, *Persian Letters*: Paris seen by two Persians.", "Swift, *Gulliver’s Travels*.", "Craig Raine’s poem “A Martian Sends a Postcard Home”: a book is a mechanical bird."],
      s:["Cliché", "Focalization", "Sensory imagery"] },
    { n:"Magical realism", a:"Realismo mágico",
      d:"The supernatural breaks into a realistic world and is narrated with complete naturalness, without astonishment from the narrator or the characters.",
      u:"Tone is the key: tell the miracle in the same register you would use for the price of bread, and with exact details. The magical element is often the visible face of a historical, social or emotional truth.",
      c:"It is not fantasy with explained rules: the magic is not justified. And the label has been overused for any writer from Latin America; it is a technique, not a nationality.",
      x:["*One Hundred Years of Solitude*: Remedios the Beauty ascends to heaven while folding sheets.", "Toni Morrison, *Beloved*: the dead daughter returns in the flesh.", "Salman Rushdie, *Midnight’s Children*.", "José Saramago, *Baltasar and Blimunda*: Blimunda sees inside people and gathers wills."],
      s:["Verisimilitude", "Tone", "Allegory", "The fantastic"] },
    { n:"Constrained writing", a:"Constraint · Oulipo",
      d:"Imposing an arbitrary formal rule on the text: not using a letter, following a mathematical scheme, telling the same story ninety-nine ways. The French group Oulipo (founded 1960) made it a method.",
      u:"A constraint forces solutions that would never occur in freedom. It is an excellent exercise: rewrite a scene without adjectives, entirely in dialogue, in a single sentence, in exactly one hundred words.",
      c:"A constraint the reader cannot perceive, and that does not improve the text, is a private game.",
      x:["Raymond Queneau, *Exercises in Style*: one trivial episode told 99 ways.", "Georges Perec, *A Void* (*La Disparition*): a whole novel without the letter “e” — and Gilbert Adair’s English translation also avoids it.", "Ernest Vincent Wright, *Gadsby* (1939): 50,000 words without an “e.”", "The drabble (exactly 100 words), six-word stories, the haiku."],
      s:["Pastiche and parody", "Mosaic novel"] }
  ]}
]});

/* ============ PLANNING AND STRUCTURE METHODS ============ */
SUPPORT.push({ key:"metodos", name:"Planning & Structure Methods", kicker:"Method",
  intro:"Models and processes for planning, structuring and revising a long narrative. Structures describe the shape stories tend to take; working methods tell you how to get there. None of them is a recipe: they are maps for when you are lost and checklists for when something is not working. Several describe the same curve under different names — choose the one that speaks to you, or combine them.",
  groups:[
  { name:"Plot structures", items:[
    { n:"Three-act structure", a:"Setup · confrontation · resolution",
      d:"The most widespread model, rooted in Aristotle’s beginning, middle and end and codified for film by Syd Field (*Screenplay*, 1979). Act I (about 25%): the world, the protagonist, the inciting incident and the decision that launches the adventure. Act II (about 50%): rising obstacles, the midpoint, the crisis. Act III (about 25%): climax and resolution.",
      u:"A good first map for any story. Mark five moments — inciting incident, first plot point, midpoint, second plot point (all is lost), climax — and check that they fall roughly in place.",
      c:"The percentages are averages, not laws. Act II is long: split it in two at the midpoint, or it will sag.",
      x:["*Pride and Prejudice*: I — Bingley and Darcy arrive; II — the refusal, the letter, Pemberley, Lydia’s elopement; III — the second proposal.", "*Star Wars*: I — Tatooine; II — the Death Star; III — the final battle."],
      t:"Use Books as the acts of a story, or mark the acts in Chapter names.",
      s:["Inciting incident", "Point of no return", "Midpoint", "All is lost", "Climax", "Freytag’s pyramid"] },
    { n:"Freytag’s pyramid", a:"Five-act structure · dramatic arc",
      d:"The model proposed by Gustav Freytag in *Technique of the Drama* (1863), based on classical tragedy and Shakespeare: exposition, rising action, climax (here in the middle: the turning point of the hero’s fortune), falling action, and catastrophe or dénouement.",
      u:"Useful for tragedies and stories of downfall, in which the hero peaks halfway and the second half is the consequence. For most modern stories, the climax sits much closer to the end.",
      c:"Taught in schools as if every story were a symmetrical pyramid; applied literally to a thriller it puts the climax far too early.",
      x:["*Macbeth*: rises to the murder of Banquo and the banquet (Act III); from then on, falls.", "*Romeo and Juliet*: Tybalt’s death, halfway through, turns everything.", "*Julius Caesar*: the assassination at the center, the consequences after."],
      s:["Three-act structure", "Climax", "Resolution", "Recognition and reversal"] },
    { n:"Hero’s journey", a:"Monomyth (Joseph Campbell) · twelve stages (Christopher Vogler)",
      d:"A pattern common to myths around the world, described by Campbell in *The Hero with a Thousand Faces* (1949) and adapted for writers by Vogler in *The Writer’s Journey*. The twelve stages: ordinary world; call to adventure; refusal of the call; meeting the mentor; crossing the first threshold; tests, allies and enemies; approach to the inmost cave; the ordeal; reward; the road back; resurrection; return with the elixir.",
      u:"Excellent for adventure, fantasy and coming-of-age stories. Read the stages as functions, not compulsory scenes: they can change order, merge or be missing.",
      c:"Followed to the letter, it produces predictable stories, and its universality has been questioned — it fits some traditions much better than others.",
      x:["The *Odyssey*; *The Hobbit*; *Star Wars* (George Lucas drew directly on Campbell).", "*Harry Potter and the Philosopher’s Stone*; *The Lion King*; *The Matrix*."],
      s:["Mentor", "Point of no return", "Character arc", "Story circle", "Heroine’s journey", "Archetype"] },
    { n:"Heroine’s journey", a:"Maureen Murdock (1990)",
      d:"A response to the hero’s journey, centerd on an inner quest. In broad strokes: separation from the feminine; identification with the masculine and success by its rules; a sense of emptiness and spiritual aridity; descent; reconnection with the feminine; healing the split; integration of both. (Other versions exist, notably Gail Carriger’s, which stresses community and connection over solitary triumph.)",
      u:"A good model for stories in which external triumph comes early and proves hollow, and the real journey is one of reconciliation and identity — whatever the character’s gender.",
      c:"Reading it as a set of rules about women’s stories, rather than as one more shape among many, narrows it.",
      x:["Frequently cited applications: *Jane Eyre*; Elsa in *Frozen*; *Brave*; Katniss across the *Hunger Games* trilogy."],
      s:["Hero’s journey", "Character arc", "Want and need"] },
    { n:"Save the Cat", a:"Blake Snyder’s fifteen-beat sheet (2005)",
      d:"A beat sheet created for screenplays and adapted to the novel by Jessica Brody: 1) opening image; 2) theme stated; 3) setup; 4) catalyst; 5) debate; 6) break into two; 7) B story; 8) fun and games (the promise of the premise); 9) midpoint; 10) bad guys close in; 11) all is lost; 12) dark night of the soul; 13) break into three; 14) finale; 15) final image. The title refers to the advice to show the hero early doing something that makes us like them — saving a cat.",
      u:"The most detailed of the current models: it says what should happen and roughly when. Great for diagnosing a middle that drags. The B story (usually a relationship) carries the theme.",
      c:"It has been blamed for standardizing commercial cinema: use it as a diagnosis, not a mould.",
      x:["The opening and final images should be the “before” and “after” of the character.", "“Fun and games”: lessons and Quidditch at Hogwarts; the training and first days of the Games in *The Hunger Games*."],
      s:["Three-act structure", "Midpoint", "All is lost", "Circular narrative", "Seven-point story structure", "Subplot"] },
    { n:"Story circle", a:"Dan Harmon’s embryo",
      d:"A condensed version of the hero’s journey in eight steps arranged in a circle: 1) a character is in a zone of comfort; 2) but they want something; 3) they enter an unfamiliar situation; 4) adapt to it; 5) get what they wanted; 6) pay a heavy price for it; 7) return to their familiar situation; 8) having changed. The top half of the circle is order; the bottom half, chaos.",
      u:"Simple and fast: it works for a novel, a chapter, an episode or a secondary character’s arc. Good for checking that change actually happens.",
      c:"Because it fits almost anything, it can give a false sense that a story works; check that step 6 really costs something.",
      x:["Used by Harmon on *Community* and *Rick and Morty*, episode by episode.", "*The Hobbit*: hobbit-hole → wants (or is pushed into) adventure → the wild → trials → the treasure → the battle → home → no longer the same."],
      s:["Hero’s journey", "Circular narrative", "Character arc", "Story spine"] },
    { n:"Seven-point story structure", a:"Dan Wells, after the Star Wars roleplaying game manual",
      d:"Seven milestones: hook (the starting state, the opposite of the ending); plot turn 1 (conflict enters); pinch point 1 (pressure that forces action); midpoint (from reaction to action); pinch point 2 (the worst moment); plot turn 2 (the last piece needed); resolution.",
      u:"Plan it backwards: start with the resolution, define the hook as its opposite, then the midpoint, the two plot turns and finally the pinch points. It can be applied to each thread — main plot, romance, inner arc — and the threads then braided together.",
      c:"Seven points are a skeleton, not a book: between them you still need the scenes that make each turn credible.",
      x:["*Harry Potter and the Philosopher’s Stone*: hook — the orphan in the cupboard under the stairs; resolution — he defeats Voldemort and finds a home."],
      t:"One Story Arc per thread, each with its seven points, lets you see whether milestones from different threads fall in the same Scenes.",
      s:["Three-act structure", "Planning backwards", "Midpoint", "Interlacing"] },
    { n:"Fichtean curve", a:"John Gardner, *The Art of Fiction*",
      d:"The story starts right in the rising action, with no prior exposition, and moves through a series of ever more serious crises up to the climax, at about two-thirds or three-quarters of the way through; a brief falling action follows. Context is supplied along the way.",
      u:"Good for thrillers, crime fiction, short stories and any story that must grip from the first page. Each crisis is a mini-climax with its own turn.",
      c:"Crisis after crisis with no variation of intensity flattens into noise; each peak must be higher than the last, and the reader needs a breath between them.",
      x:["Most thrillers and adventure novels.", "*The Wizard of Oz*: tornado, witch, forest, flying monkeys — crisis after crisis."],
      s:["In medias res", "Try-fail cycles", "Obstacles and complications", "Exposition and incluing"] },
    { n:"Kishōtenketsu", a:"The four-part East Asian structure",
      d:"A classical Chinese, Korean and Japanese structure: *ki* (introduction), *shō* (development), *ten* (twist: a new and unexpected element, apparently unrelated) and *ketsu* (conclusion, which reconciles the twist with what came before). It is not built on a central conflict: interest comes from contrast and change of perspective.",
      u:"An alternative for contemplative, everyday or gently mysterious stories — or for chapters and short stories. Its strength lies in the twist and in how it makes you reread the beginning.",
      c:"Western readers trained on conflict may find it slow if the *ten* is weak; the twist must genuinely reframe things.",
      x:["Four-panel comic strips (*yonkoma*) in manga.", "Studio Ghibli films such as *My Neighbor Totoro*.", "Level design in Nintendo games: introduce an idea, develop it, twist it, conclude."],
      s:["Three-act structure", "Plot twist", "Tone"] },
    { n:"The seven basic plots", a:"Christopher Booker (2004)",
      d:"The thesis that almost all stories follow one of seven patterns: overcoming the monster; rags to riches; the quest; voyage and return; comedy; tragedy; rebirth.",
      u:"Not a planning method, but it helps you understand what kind of story you are telling and what expectations readers bring. Many books combine two or three.",
      c:"Booker’s categories are broad enough that almost anything fits; use them to locate your story, not to prove it is “correct.”",
      x:["Overcoming the monster: *Beowulf*, *Dracula*, *Jaws*.", "Rags to riches: *Cinderella*, *Jane Eyre*, *Great Expectations*.", "The quest: *The Lord of the Rings*. Voyage and return: *Alice’s Adventures in Wonderland*.", "Tragedy: *Macbeth*. Rebirth: *A Christmas Carol*."],
      s:["Premise and logline", "Hero’s journey", "Folk tale and fable"] },
    { n:"MICE quotient", a:"Milieu · Idea (Inquiry) · Character · Event (Orson Scott Card)",
      d:"Four kinds of story thread, each with its own beginning and end. Milieu: begins when the character enters a place and ends when they leave. Idea (or Inquiry): begins with a question and ends with the answer. Character: begins with dissatisfaction with oneself and ends with change (or acceptance). Event: begins with a disruption of order and ends with a new order.",
      u:"Identify which threads you open and close them in reverse order, like nested brackets: the first opened is the last closed (Mary Robinette Kowal popularized this nesting). It explains many unsatisfying endings — the book answered a question it had never asked.",
      c:"Opening an Event story and closing it with a Character epiphany (or vice versa) is the most common mismatch.",
      x:["Milieu: *Gulliver’s Travels*. Idea: any whodunit. Character: *Emma*. Event: *The Lord of the Rings*.", "Nesting: a crime opens (Idea), then the detective’s crisis (Character); the crisis is resolved first, the crime last."],
      s:["Dramatic question", "Interlacing", "Subplot"] },
    { n:"Story spine", a:"Kenn Adams (improv theater) · popularized by Pixar",
      d:"A fill-in-the-blanks skeleton from improvisational theater: Once upon a time… Every day… One day… Because of that… Because of that… Until finally… And ever since then… It insists on the causal chain (“because of that”), not on a sequence of “and then.”",
      u:"Use it to tell your whole book in a paragraph before you start, or to test a draft: if you cannot connect the middle events with “because of that,” the plot is episodic. Add as many “because of that” lines as you need.",
      c:"Its simplicity hides subplots and interiority; it is a test of causality, not a full plan.",
      x:["“Once upon a time there was a widowed clownfish. Every day he guarded his only son. One day the son was taken by a diver. Because of that, he crossed the ocean… Until finally he found him. And ever since then, he has let him swim.” (*Finding Nemo*)"],
      s:["Premise and logline", "Story circle", "Story and plot"] }
  ]},
  { name:"Working methods", items:[
    { n:"Plotting or pantsing", a:"Architects and gardeners · plotters and pantsers (“flying by the seat of your pants”)",
      d:"The two poles of the writing process. The plotter (architect) plans everything before writing; the pantser (gardener) plants a seed and discovers the story while writing — the architect/gardener image is George R. R. Martin’s. Most writers sit somewhere in between (“plantsers”).",
      u:"Planning saves rewriting and avoids dead ends; discovery brings freshness and surprise — but you pay for it in revision. A common compromise: know the ending and two or three milestones, and discover the road. E. L. Doctorow compared writing to driving at night: you only see as far as the headlights, but you can make the whole trip that way.",
      c:"Neither method is more “authentic.” Pantsers risk saggy middles and abandoned threads; plotters risk mechanical scenes and losing interest in a story already told in the outline.",
      x:["Plotters: J. K. Rowling, with handwritten grids of chapters and threads; John Irving, who writes the last sentence first.", "Pantsers: Stephen King, who in *On Writing* describes starting from a situation and following it."],
      s:["Snowflake method", "Zero draft", "Planning backwards", "Step outline"] },
    { n:"Premise and logline", a:"“What if…?” · elevator pitch",
      d:"The story summed up in one or two sentences: who (protagonist), wants what (goal), against whom or what (obstacle), and what is at stake. Many stories start from a question: “What if…?”",
      u:"Write it before you start and return to it when you get lost. If it will not fit into two sentences, the story may not be clear yet. A good premise contains an irony or internal tension.",
      c:"A logline that describes the setting or theme but not a character with a goal (“a novel about grief in a small town”) is not yet a story.",
      x:["“What if dinosaurs were cloned for a theme park?” (*Jurassic Park*)", "“What if death stopped killing?” (Saramago, *Death at Intervals*)", "“A scientist brings a creature to life and abandons it; the creature demands a reckoning.” (*Frankenstein*)", "“A girl volunteers to die in her sister’s place in a televised contest that only one can survive.” (*The Hunger Games*)"],
      s:["Dramatic question", "Snowflake method", "Stakes", "Synopsis"] },
    { n:"Snowflake method", a:"Randy Ingermanson",
      d:"Planning by successive expansion, like a fractal, in ten steps: 1) a one-sentence summary of the novel; 2) a paragraph (setup, three disasters, ending); 3) a summary sheet for each character (goal, motivation, conflict, epiphany); 4) each sentence of the paragraph becomes a paragraph — a one-page synopsis; 5) a page per main character, from their point of view; 6) a four-page synopsis; 7) full character charts; 8) a list of scenes, in a spreadsheet; 9) (optional) a narrative description of each scene; 10) the first draft.",
      u:"Ideal for those who like to plan but want room to adjust: each step corrects the previous ones, and structural problems surface before three hundred pages have been written.",
      c:"Ten steps can become a way of never starting the draft; stop planning as soon as you know enough to write.",
      x:["Step 1 for *Pride and Prejudice*: “A sharp-tongued young woman without a fortune refuses the richest man she knows — and discovers she was wrong about him and about herself.”", "Step 2: one sentence for the setup, one for each of the three disasters, one for the ending."],
      t:"Step 8 — the scene list — is the Narrative board: one Scene per card, with POV Character and summary.",
      s:["Premise and logline", "Step outline", "Want and need", "Plotting or pantsing"] },
    { n:"Step outline", a:"Scene-by-scene outline · index cards · beat outline",
      d:"An ordered list of every scene, each summarized in one or two lines: who, where, what changes. It is the technique of index cards pinned to a wall, used by screenwriters and by Nabokov, who wrote his novels on cards.",
      u:"Write one card per scene and shuffle them until the order works. For each scene, note POV, goal, conflict and what changes between entry and exit. A scene in which nothing changes is a candidate for cutting.",
      c:"An outline in which every card says “they talk about X” describes topics, not scenes; write the change, not the subject.",
      x:["Card: “12. Kitchen, night. POV Anna. She wants her brother to sign the sale of the house; he refuses and reveals that their mother left him a letter. Change: Anna no longer trusts her mother.”", "Vladimir Nabokov drafted *Lolita* on index cards that he kept reshuffling."],
      t:"This is what the tool is for: each Scene is a card, you drag it with a long press, and the lanes show which Story Arc it belongs to.",
      s:["Snowflake method", "Scene and sequel", "Layered revision", "Scene and summary"] },
    { n:"Planning backwards", a:"Reverse planning · writing toward the ending",
      d:"Starting from the outcome — the climax, the revelation, the final image — and building backwards everything needed to get there.",
      u:"Indispensable for mysteries and twist stories: first decide the truth, then how to hide it. Ask at each step: “For this to happen, what had to happen before?”",
      c:"An ending decided too rigidly can force characters to act against their nature to get there; let the plan bend when the characters push back.",
      x:["Agatha Christie began with the crime and the culprit.", "Edgar Allan Poe, in “The Philosophy of Composition” (1846), argues that every plot must be worked out from its dénouement.", "John Irving writes the last sentence before he begins."],
      s:["Seven-point story structure", "Plot twist", "Setup and payoff", "Foreshadowing"] },
    { n:"Want and need", a:"Goal, motivation, conflict (GMC, Debra Dixon)",
      d:"The basis of any active character. Want: the external goal, concrete and conscious. Need: the inner necessity, often ignored by the character. Between them, a lie the character believes. Debra Dixon’s GMC formula sums it up in one sentence: “[Character] wants [goal] because [motivation], but [conflict].”",
      u:"Fill in the sentence for every important character — antagonist included — on both the external and the internal level. Kurt Vonnegut advised that every character should want something, even if it is only a glass of water.",
      c:"A goal that is vague (“to be happy”) gives no scenes; a need the author states in the text (“she needed to learn to trust”) becomes a sermon.",
      x:["Elizabeth Bennet wants a marriage for love and needs to recognize her own prejudices.", "Gatsby wants Daisy; he needed to let go of the past.", "Pip wants to be a gentleman; he needs to learn what a gentleman is."],
      t:"The Character details panel is the right place for these three lines.",
      s:["Character arc", "Tragic flaw", "Stakes", "Dilemma"] },
    { n:"Zero draft", a:"Discovery draft · vomit draft · NaNoWriMo",
      d:"Writing the story from beginning to end as fast as possible, without rereading or correcting, simply to find out what it is. Anne Lamott, in *Bird by Bird*, defended the “shitty first draft” everyone is entitled to; Terry Pratchett said the first draft is just you telling yourself the story.",
      u:"Set a daily target, do not go back, and leave markers wherever something is missing (“[check date],” “[argument scene here]”). National Novel Writing Month — 50,000 words in November — is built on this idea.",
      c:"A zero draft is not a book: it is raw material. The real work begins in revision.",
      x:["A common habit: type “TK” or “XXX” in place of a missing word or fact and keep going, then search for the markers later."],
      s:["Plotting or pantsing", "Layered revision", "Kill your darlings"] },
    { n:"Layered revision", a:"Reverse outline · revision in passes · macro to micro",
      d:"Revising in several passes, each with a single goal, from largest to smallest: first structure (order, cuts, holes), then scenes (goal, conflict, turn), then characters (consistency, voice), and only at the end the sentence (rhythm, repetitions, spelling). A reverse outline is a step outline of what is actually on the page, to see the book’s real shape.",
      u:"Let the text rest for a few weeks. Make the reverse outline and compare it with the plan. Do not polish sentences in scenes that may be cut. Read aloud in the final pass.",
      c:"Line-editing chapter one for the twelfth time while the ending is still broken is the most common trap.",
      x:["First-pass questions: does the story start in the right place? Does every scene change something? Is everything planted paid off? Could two characters be merged into one?", "Last-pass questions: are words repeated on the same page? Do all sentences start the same way?"],
      t:"Rebuilding the written book on the Narrative board — Scene by Scene, with POV Character and Story Arc — is a reverse outline: imbalances jump out (a thread that disappears for ten Chapters, a Character who never comes back).",
      s:["Step outline", "Zero draft", "Setup and payoff", "Late in, early out", "Beta readers"] },
    { n:"Kill your darlings", a:"“Murder your darlings” (Arthur Quiller-Couch, 1914)",
      d:"Revision advice: be ready to cut the passages you are proudest of when they do not serve the work. Quiller-Couch’s original target was ornate “fine writing”; the phrase is often misattributed to Faulkner or King, who repeated it.",
      u:"When a passage survives every revision only because you love it, ask what it does for the scene. Keep a “cuts” file: knowing nothing is lost for ever makes cutting easier, and some darlings find a better home later.",
      c:"It does not mean cutting everything beautiful; it means that beauty must also work. Over-cutting leaves a dry, voiceless text.",
      x:["Typical darlings: a brilliant description in the middle of a chase; a witty exchange that repeats the joke of a previous scene; a beloved minor character with no function."],
      s:["Layered revision", "Chekhov’s gun", "Purple prose"] },
    { n:"Five commandments of storytelling", a:"Story Grid (Shawn Coyne)",
      d:"According to this analytical method, every narrative unit — scene, sequence, act, book — has five elements: inciting incident; progressive complication culminating in a turning point; crisis (a hard choice); climax (the choice made); resolution.",
      u:"A checklist for scenes that “don’t work”: almost always the crisis is missing — the character does not really have to choose. The method also asks you to know your genre and the obligatory scenes its readers expect.",
      c:"Applied mechanically to every paragraph, it turns into accounting; use it on scenes that feel flat.",
      x:["Obligatory scenes: the meet-cute and the proof of love in a romance; the discovery of the body and the unmasking of the culprit in a mystery; the hero at the mercy of the villain in a thriller."],
      s:["Scene and sequel", "Dilemma", "Climax", "Inciting incident", "Literary and genre fiction"] },
    { n:"Series bible", a:"Story bible · continuity file",
      d:"The document recording everything already fixed in the story’s universe: character sheets (age, looks, tics, what they know and since when), timeline, maps, rules of the world, vocabulary, decisions made.",
      u:"Indispensable for sagas, series and stories with large casts: it prevents eyes that change color and dead characters who come back. Update it as you write, not afterwards.",
      c:"A bible that grows into a hobby of its own can replace the writing; record what is on the page and what you have decided, not everything you could invent.",
      t:"The tool is partly exactly this: Character details, Story Arcs with both orders, Sceneries, and References and Notes attached to each element, across several Books.",
      x:["Tolkien’s chronologies and appendices.", "J. K. Rowling’s grids with one column per plot thread.", "Television series bibles, handed to new writers when they join the room."],
      s:["Worldbuilding", "Step outline", "Interlacing"] },
    { n:"Theme as a question", a:"Thematic argument · controlling idea",
      d:"Theme is what the story is about beneath the plot. It works better phrased as an open question (“How far can one go for love?”) than as a lesson (“Love conquers all”).",
      u:"Have the characters give different answers to the same question — protagonist, antagonist, subplots — and let the climax put them to the test. Theme is often discovered only at the end of the first draft; it is strengthened in revision, through motifs and echoes.",
      c:"A character who announces the moral of the story turns the novel into a sermon.",
      x:["*Frankenstein*: what does a creator owe his creation?", "*Great Expectations*: what makes a gentleman?", "José Saramago, *Blindness*: what remains of humanity when no one can see us?"],
      s:["Motif", "Subplot", "Symbol", "Premise and logline"] },
    { n:"Beta readers", a:"Critique partners · writing groups · test readers",
      d:"Readers who see the manuscript before publication and report their experience of it: where they got bored, confused, moved or ahead of the plot. Alpha readers see early drafts; beta readers a nearly finished version; sensitivity readers check the portrayal of specific communities or experiences.",
      u:"Ask specific questions (“Where did you stop wanting to read?,” “When did you guess the culprit?”). Treat their reactions as data and their solutions as suggestions. If several readers stumble in the same place, there is a problem there — even if their diagnoses differ.",
      c:"Showing the draft too early, to too many people, or only to people who love you produces noise or flattery. Do not rewrite after every comment.",
      x:["Neil Gaiman’s often-quoted advice: when people tell you something is wrong, they are usually right; when they tell you how to fix it, they are usually wrong."],
      s:["Layered revision", "Synopsis"] },
    { n:"Synopsis", a:"Outline for agents and editors · one-page summary",
      d:"A summary of the whole story, ending included, written in the present tense and the third person, usually one or two pages long. It is both a submission document and a planning tool.",
      u:"Follow the main character’s arc and the chain of cause and effect; name only the characters who matter; reveal the ending — an agent needs to see that it works. Writing it before or after the draft quickly shows whether the plot hangs together.",
      c:"Common mistakes: hiding the ending to create suspense, listing every subplot, writing in the style of back-cover copy (“Will she survive?”), and summarizing chapter by chapter instead of story.",
      x:["Opening of a synopsis: “When seventeen-year-old Mara inherits her grandmother’s failing ferry business, she must keep it afloat for one summer or watch the island lose its only link to the mainland.”"],
      s:["Premise and logline", "Snowflake method", "Story spine"] }
  ]}
]});

/* ============ NARRATIVE STYLES, GENRES AND MOVEMENTS ============ */
SUPPORT.push({ key:"estilos-narrativos", name:"Narrative Styles & Genres", kicker:"Narrative style",
  intro:"The great ways of telling a story: literary movements (what an age thought a novel should be), narrative genres (the kind of book and what readers expect from it) and ways of writing prose. Knowing them helps you choose on purpose — and mix with your eyes open. Examples favor literature written in English, alongside the world classics every writer reads.",
  groups:[

  { name:"Movements and periods", items:[
    { n:"Romanticism", a:"Late 18th to mid-19th century",
      d:"The movement that put feeling, individuality, nature, the national past, the imagination and freedom at the center of literature. In English it begins in poetry (Wordsworth and Coleridge’s *Lyrical Ballads*, 1798) and gives fiction the historical novel of Walter Scott, the Gothic novel and the passionate novels of the Brontës; in America, Hawthorne, Poe and Melville.",
      u:"Useful legacy today: characters driven by absolute passions, conflicts between the individual and society (family, honor, class), landscapes that mirror states of mind, a fascination with ruins, the Middle Ages and the sublime, tragic destiny. It works in historical novels, passionate dramas and any story of impossible love.",
      c:"Romantic excess (tears, fainting fits, providential coincidences) has aged badly; use the intensity, not the mannerisms. A Romantic character needs a world that resists, or the passion is just noise.",
      x:["Emily Brontë, *Wuthering Heights* (1847).", "Mary Shelley, *Frankenstein* (1818).", "Walter Scott, *Ivanhoe* (1819).", "Nathaniel Hawthorne, *The Scarlet Letter* (1850); Victor Hugo, *Notre-Dame de Paris* (1831)."],
      s:["Victorian novel", "Historical novel", "Pathos, sentimentality and bathos", "Gothic mode", "Pathetic fallacy"] },
    { n:"Victorian novel", a:"Britain, c. 1837–1901 · the great realist tradition in English",
      d:"The long, multi-plotted novel of the Victorian age, often first published in monthly parts or magazine serials: broad social canvases, moral seriousness, an omniscient narrator who comments and judges, and a strong interest in class, money, marriage, industry and reform.",
      u:"A model for big ensemble novels: several interwoven plots, a whole town or society in view, a narrator with a personality, and chapters built to end on a pull. George Eliot shows how to combine that breadth with deep psychological insight.",
      c:"Copied naively, it brings coincidences, convenient inheritances, sermonizing narrators and saccharine deathbeds. Modern readers accept the scope but not the moralizing.",
      x:["Charles Dickens, *Bleak House* (1852–53).", "George Eliot, *Middlemarch* (1871–72).", "Thackeray, *Vanity Fair* (1847–48); Elizabeth Gaskell, *North and South* (1854–55).", "Thomas Hardy, *Tess of the d’Urbervilles* (1891), already turning toward naturalism."],
      s:["Realism and naturalism", "Novel of manners", "Intrusive narrator", "Subplot", "Short chapters and cliffhangers"] },
    { n:"Aestheticism and Decadence", a:"Late 19th century · “art for art’s sake”",
      d:"A reaction against Victorian moralism and against realism: art exists for beauty, not instruction. Decadence adds a taste for artifice, sickness, ennui, transgression and the end of an era. Closely linked to French Symbolism, which preferred suggesting the world — through symbol, the music of the sentence, sensation — to describing it.",
      u:"Useful for narratives of atmosphere and sensibility: characters dissolving into what they feel, settings that are states of mind, rhythmic sentences and repeated images, epigrammatic wit. Wilde shows how aphorism can carry both character and theme.",
      c:"It can become vague, precious or merely ornamental. Suggestion only works when there is something concrete behind the symbol.",
      x:["Oscar Wilde, *The Picture of Dorian Gray* (1890).", "J.-K. Huysmans, *Against Nature* (*À rebours*, 1884), the breviary of Decadence.", "Walter Pater, *Marius the Epicurean* (1885)."],
      s:["Poetic prose", "Symbol", "Atmosphere", "Literary impressionism", "Purple prose"] },
    { n:"Modernism", a:"First decades of the 20th century",
      d:"A break with inherited forms: fragmentation, multiple points of view, stream of consciousness, subjective time, experiments with language. Ezra Pound’s slogan “Make it new” sums it up; its annus mirabilis is 1922 (*Ulysses*, *The Waste Land*).",
      u:"Modernism gave the novel the tools of interiority: interior monologue, shifting focalization, psychological rather than chronological time. Use them when the story lives more in the characters’ minds than in events.",
      c:"Imitating modernist difficulty without its necessity produces obscure texts. The great modernists are difficult because what they want to say does not fit traditional form.",
      x:["James Joyce, *Ulysses* (1922).", "Virginia Woolf, *Mrs Dalloway* (1925) and *To the Lighthouse* (1927).", "William Faulkner, *The Sound and the Fury* (1929).", "Fernando Pessoa and the Portuguese *Orpheu* group (1915)."],
      s:["Stream of consciousness", "Interior monologue", "Nonlinear narrative", "Multiple narrators", "Epiphany"] },
    { n:"Lost Generation", a:"American expatriates of the 1920s",
      d:"Gertrude Stein’s name, popularized by Hemingway, for the generation that came of age in the First World War, many of whom lived in Paris in the 1920s. Their fiction is marked by disillusion, restless pleasure-seeking and a pared-down style that left the trauma unspoken.",
      u:"A model for stories of a damaged generation told through surfaces: parties, drinking, travel, talk that circles what cannot be said. Fitzgerald shows how lyrical prose can expose an empty glamour; Hemingway how restraint can carry grief.",
      c:"Imitations reproduce the cocktails and the short sentences but not the wound underneath; without it, the result is just glamour or terseness.",
      x:["Ernest Hemingway, *The Sun Also Rises* (1926).", "F. Scott Fitzgerald, *The Great Gatsby* (1925).", "John Dos Passos, *Manhattan Transfer* (1925)."],
      s:["Modernism", "Minimalism", "Iceberg theory", "Subtext"] },
    { n:"Harlem Renaissance", a:"New York, 1920s–1930s",
      d:"The flowering of African American literature, music and art centerd on Harlem. Fiction and poetry explored Black identity, the Great Migration, passing, folk culture and the rhythms of blues and jazz, in deliberate dialogue with — and against — white expectations.",
      u:"It shows how to give literary form to speech, music and community life, and how to write about race through specific individuals rather than types. Zora Neale Hurston’s use of dialect within a lyrical narrative frame remains a lesson in voice.",
      c:"Rendering dialect is delicate: done from outside or for comic effect, it slides into caricature. Hurston’s strength came from deep knowledge and respect.",
      x:["Zora Neale Hurston, *Their Eyes Were Watching God* (1937).", "Nella Larsen, *Passing* (1929).", "Jean Toomer, *Cane* (1923); Langston Hughes, *Not Without Laughter* (1930)."],
      s:["Idiolect and speech patterns", "Dialect and regionalism", "Lyrical style", "Mosaic novel"] },
    { n:"Social realism", a:"The proletarian and social-protest novel · 1930s onwards",
      d:"Fiction of social commitment: it portrays workers, farmers and the poor, exploitation and collective struggle, often influenced by Marxism and journalism. In the US it peaks in the Depression; in Britain it returns in the working-class novels of the 1950s; in Portugal it took the form of neo-realism (Alves Redol’s *Gaibéus*, 1939), and in Italy of neorealism in film and fiction.",
      u:"Useful for stories whose protagonist is a group, a class or a community, and in which economic conditions decide the characters’ fate. It teaches documentation (Steinbeck traveled with migrant workers) and giving a voice to those who seldom had one.",
      c:"An ideological thesis on display turns characters into symbols and the novel into a pamphlet. The best social realists tell injustice through concrete people and careful writing.",
      x:["John Steinbeck, *The Grapes of Wrath* (1939).", "Richard Wright, *Native Son* (1940).", "Robert Tressell, *The Ragged-Trousered Philanthropists* (1914); Alan Sillitoe, *Saturday Night and Sunday Morning* (1958).", "Upton Sinclair, *The Jungle* (1906), a precursor."],
      s:["Realism and naturalism", "Novel of manners", "Mosaic novel", "Dialect and regionalism", "Reportage style"] },
    { n:"Southern Gothic", a:"The American South, 20th century",
      d:"A strand of American fiction that uses Gothic elements — decay, the grotesque, violence, family secrets, religious obsession — to expose the moral damage of the South: slavery and its aftermath, poverty, isolation and pride.",
      u:"It shows how the uncanny can arise from history and society rather than ghosts. Grotesque characters, a decaying house or town, and a comic-horrific tone can carry a serious moral vision.",
      c:"Grotesque characters used only for shock, or as backward stereotypes, betray the tradition, whose writers saw their freaks with compassion.",
      x:["William Faulkner, “A Rose for Emily” (1930).", "Flannery O’Connor, “A Good Man Is Hard to Find” (1953).", "Carson McCullers, *The Heart Is a Lonely Hunter* (1940); Harper Lee, *To Kill a Mockingbird* (1960) draws on it.", "Cormac McCarthy, *Child of God* (1973)."],
      s:["Gothic mode", "Atmosphere", "Black humor", "Caricature and the grotesque"] },
    { n:"Surrealism", a:"Europe, from 1924 (André Breton’s manifesto)",
      d:"A movement seeking to free the imagination from the control of reason: dreams, chance, the unconscious, free association, absurd humor. In English, its influence runs through Leonora Carrington’s fiction, Angela Carter and much later fabulism.",
      u:"In narrative, surrealism serves for dream sequences, for the dream-logic of a short story, and for unexpected images that reveal what a character does not know they feel. The short story is its natural format.",
      c:"Weirdness for its own sake quickly wears thin. Even a surrealist story needs an inner logic and an emotional center.",
      x:["Leonora Carrington, *The Hearing Trumpet* (1974).", "André Breton, *Nadja* (1928).", "Angela Carter, *The Infernal Desire Machines of Doctor Hoffman* (1972), surrealism’s English heir."],
      s:["The absurd", "Magical realism", "Black humor", "Defamiliarization"] },
    { n:"Existentialism", a:"Mid-20th century",
      d:"A philosophical and literary current centerd on freedom, anguish, the absurdity of existence and the responsibility of choosing without guarantees. In literature: Sartre, Camus, Simone de Beauvoir; in English, its echoes reach Iris Murdoch, Richard Wright and Walker Percy.",
      u:"Put a character before a choice that no outside rule can resolve. The tension comes from consciousness: what the character knows about themself and the world, and what they do with it. It works in spare, reflective, often first-person narratives.",
      c:"The risk is the thesis character who lectures about the absurd instead of living it. A concrete situation (a crime, a plague, a remote village) must carry the idea.",
      x:["Albert Camus, *The Stranger* (1942) and *The Plague* (1947).", "Jean-Paul Sartre, *Nausea* (1938).", "Walker Percy, *The Moviegoer* (1961)."],
      s:["The absurd", "Psychological novel", "Essayistic style", "Dilemma"] },
    { n:"Nouveau roman", a:"The “new novel” · France, 1950s–60s",
      d:"A French movement (Alain Robbe-Grillet, Nathalie Sarraute, Michel Butor, Claude Simon) that rejected the psychological character and traditional plot: minute, objective descriptions, repetitions, scrambled time, the reader left to reconstruct the story.",
      u:"Useful as a laboratory: “objective” description that betrays an obsession, the repetition of a scene with small variations, the second-person novel (Butor’s *Second Thoughts*). Its influence reaches English-language writers such as Christine Brooke-Rose and B. S. Johnson.",
      c:"Over a whole novel it demands a great deal of the reader. Today it is used mostly in parts, as a technique.",
      x:["Alain Robbe-Grillet, *Jealousy* (1957).", "Michel Butor, *La Modification* (1957; in English *Second Thoughts*), written in the second person.", "B. S. Johnson, *The Unfortunates* (1969): a novel in a box, its sections to be read in any order."],
      s:["Second person", "Third person objective", "Defamiliarization", "Constrained writing"] },
    { n:"Beat Generation", a:"United States, 1950s",
      d:"A group of American writers (Jack Kerouac, Allen Ginsberg, William S. Burroughs) who rejected postwar conformity in favor of spontaneity, travel, jazz, drugs, spirituality and sexual freedom. Kerouac’s “spontaneous prose” aimed at the rhythm of improvised jazz.",
      u:"A source for road narratives, confessional voices and breathless, rhythmic prose that captures experience as it happens. The long, rushing sentence can convey exhilaration or desperation.",
      c:"Spontaneity is a style, not an absence of craft: *On the Road* was revised over years. Unedited “flow” usually reads as self-indulgence.",
      x:["Jack Kerouac, *On the Road* (1957).", "William S. Burroughs, *Naked Lunch* (1959).", "Allen Ginsberg, *Howl* (1956), poetry."],
      s:["Travel writing", "Long sentences", "Autofiction", "Stream of consciousness"] },
    { n:"Postmodernism", a:"From the 1960s–70s",
      d:"Fiction that plays with itself: metafiction, parody, intertextuality, mixing of genres and registers, distrust of grand narratives, ironic rewriting of history.",
      u:"Use it to rewrite history from the margins (those left out of the books), for narrators who comment on their own narration, for collages of documents and voices.",
      c:"Excessive irony and self-reference distance readers from the story. The great postmodern novels are, first of all, good stories.",
      x:["Thomas Pynchon, *The Crying of Lot 49* (1966).", "John Fowles, *The French Lieutenant’s Woman* (1969).", "Italo Calvino, *If on a Winter’s Night a Traveler* (1979); Umberto Eco, *The Name of the Rose* (1980).", "José Saramago, *Baltasar and Blimunda* (1982)."],
      s:["Metafiction", "Intertextuality and allusion", "Pastiche and parody", "Historical novel", "Intrusive narrator"] },
    { n:"Postcolonial fiction", a:"From the 1950s",
      d:"Fiction from or about formerly colonized societies that writes back to the imperial center: it reclaims history, language and point of view, explores divided identities, migration and the aftermath of empire, and often bends English itself to new rhythms and vocabularies.",
      u:"It teaches how to tell a story from inside a culture without explaining it for outsiders, how to mix languages and registers, and how to rewrite a canonical story from the other side.",
      c:"Writing about another culture from outside requires deep research and humility; exoticism (the culture as colorful backdrop) is the trap.",
      x:["Chinua Achebe, *Things Fall Apart* (1958).", "Jean Rhys, *Wide Sargasso Sea* (1966): *Jane Eyre* from the side of the “madwoman in the attic.”", "Salman Rushdie, *Midnight’s Children* (1981).", "Chimamanda Ngozi Adichie, *Half of a Yellow Sun* (2006)."],
      s:["Historical novel", "Magical realism", "Intertextuality and allusion", "Multiple narrators"] },
    { n:"Minimalism", a:"Dirty realism · Hemingway, Carver",
      d:"Prose pared down to the essentials: short sentences, simple vocabulary, few adjectives, curt dialogue, almost no psychological explanation. Meaning lies in what goes unsaid. It descends from Hemingway and his iceberg theory and found its short-story model in Raymond Carver (whose editor, Gordon Lish, famously cut his stories hard).",
      u:"Excellent for short stories and for lives in which emotion is held back. Cut everything the reader can infer; let gestures and silences speak.",
      c:"Done badly, it is only impoverished language and scenes without tension. Minimalism needs strong subtext; without it, there is nothing under the surface.",
      x:["Raymond Carver, *What We Talk About When We Talk About Love* (1981).", "Ernest Hemingway, “Hills Like White Elephants” (1927).", "Amy Hempel, *Reasons to Live* (1985)."],
      s:["Iceberg theory", "Subtext", "Short sentences", "Maximalism", "Plain style"] },
    { n:"Autofiction", a:"Autobiographical novel · since the 1970s",
      d:"Narrative in which the author appears as a character, under their own name or a close one, mixing facts from their life with invention. The term is Serge Doubrovsky’s (1977).",
      u:"It gives fiction the force of testimony. It works when the “I” is treated as a character — with flaws, blind spots and a trajectory — and not as a diary.",
      c:"Ethical and legal issues with recognizable real people. And navel-gazing: the author’s life only interests the reader once it is transformed into story.",
      x:["Karl Ove Knausgaard, *My Struggle* (2009–2011).", "Rachel Cusk, the *Outline* trilogy (2014–2018).", "Ben Lerner, *10:04* (2014).", "Christopher Isherwood, *Goodbye to Berlin* (1939), an early example: “I am a camera.”"],
      s:["First person — protagonist", "Unreliable narrator", "Metafiction"] }
  ]},

  { name:"Narrative genres", items:[
    { n:"Novel", a:"Long-form prose fiction",
      d:"A long prose narrative, with several characters, actions and places, that can follow a life, a family or an era. In English, anything over roughly 40,000–50,000 words is usually called a novel. It is the most flexible genre: it absorbs all the others.",
      u:"It needs a question that can sustain hundreds of pages and real development of characters. Use the structure entries (three acts, hero’s journey, story circle) to design it and the tool to keep track of Books, Chapters, Scenes and Story Arcs.",
      c:"A novel is not a stretched short story: it needs subplots, variations of pace and characters who change.",
      x:["George Eliot, *Middlemarch* (1871–72).", "Toni Morrison, *Beloved* (1987).", "Eça de Queirós, *The Maias* (1888)."],
      t:"Each Book in the tool can be one novel of a series, or one part of a long novel.",
      s:["Novella", "Short story", "Three-act structure", "Subplot"] },
    { n:"Novella", a:"Medium-length fiction",
      d:"A narrative of intermediate length between the short story and the novel — roughly 17,500 to 40,000 words by the Science Fiction and Fantasy Writers’ definition, though conventions vary: one main action, few characters, concentrated time, but more development than a story.",
      u:"A good format for a single crisis lived in depth, for a strong voice, for stories that would lose force if stretched.",
      c:"Do not add subplots to “make it a novel”: concentration is its virtue. Publishers have long found novellas hard to sell on their own — though e-books and small presses have revived the form.",
      x:["Joseph Conrad, *Heart of Darkness* (1899).", "Leo Tolstoy, *The Death of Ivan Ilyich* (1886).", "Ernest Hemingway, *The Old Man and the Sea* (1952); Claire Keegan, *Small Things Like These* (2021)."],
      s:["Novel", "Short story"] },
    { n:"Short story", a:"Short fiction · flash fiction at under about 1,000 words",
      d:"A short narrative centerd on a moment, a situation or a revelation, with few characters and great economy. It is read in one sitting, and so it stakes everything on a single effect — Poe’s “unity of effect.”",
      u:"Start late, end early; every sentence must serve the final effect. The short story often lives on a minimal change: someone realizes something, or can no longer ignore it (Joyce’s epiphany).",
      c:"A short story is not the first chapter of a novel. If the story needs more room, it is something else.",
      x:["James Joyce, *Dubliners* (1914).", "Anton Chekhov, “The Lady with the Dog” (1899); Jorge Luis Borges, *Ficciones* (1944).", "Alice Munro, *Runaway* (2004); Raymond Carver; Flannery O’Connor."],
      s:["Novella", "Late in, early out", "Minimalism", "Last line", "Epiphany"] },
    { n:"Sketch and column", a:"The newspaper sketch · personal essay · the Portuguese *crónica*",
      d:"A short piece, usually published in newspapers and magazines, that starts from everyday life — an episode, an observation, a memory — and arrives at a reflection, often with humor or lyricism. In English the tradition runs from Addison and Steele’s *Spectator* to Dickens’s *Sketches by Boz* and the modern columnist; Portuguese and Brazilian literature call it the *crónica*.",
      u:"The sketch trains voice: personal tone, rhythm, observation of detail. Many novelists were also columnists. In a novel, a columnist’s voice produces close, conversational, ironic narrators.",
      c:"In a novel, the column’s tone can scatter the narrative into digressions; use it as color, not as structure.",
      x:["Charles Dickens, *Sketches by Boz* (1836).", "E. B. White’s essays for *The New Yorker* and *Harper’s*.", "Nora Ephron, *I Feel Bad About My Neck* (2006)."],
      s:["Intrusive narrator", "Tone", "Oral style (skaz)", "Humor and the comic"] },
    { n:"Bildungsroman", a:"Coming-of-age novel · novel of formation",
      d:"A novel that follows the formation of a character — usually from childhood or youth to adulthood — through experiences, mistakes, losses and discoveries. The *Künstlerroman* is its variant about the making of an artist.",
      u:"The character arc is the plot. Choose the stages well (leaving home, first love, loss, disillusion) and what the character learns at each one.",
      c:"A string of episodes is not a formation: each stage must change the character, and the end must show who they have become.",
      x:["Goethe, *Wilhelm Meister’s Apprenticeship* (1795–96).", "Charles Dickens, *Great Expectations* (1861); Charlotte Brontë, *Jane Eyre* (1847).", "James Joyce, *A Portrait of the Artist as a Young Man* (1916), a *Künstlerroman*; J. D. Salinger, *The Catcher in the Rye* (1951)."],
      s:["Character arc", "Hero’s journey", "Want and need", "Young adult fiction"] },
    { n:"Historical novel", a:"Fiction set in a documented past",
      d:"A novel set in a reconstructed historical period, in which invented characters live alongside real events and, sometimes, real figures. It was born with Walter Scott’s *Waverley* (1814), whose subtitle, *’Tis Sixty Years Since*, set the convention of a past beyond living memory.",
      u:"Research deeply (customs, objects, language, prices, distances), then hide the research inside the scenes. Choose an angle official history did not show. For language and dialogue, see the section on older English.",
      c:"Anachronisms of mentality are worse than anachronisms of objects: characters with present-day values in an age that did not have them. Too much historical information stalls the story.",
      x:["Walter Scott, *Waverley* (1814).", "Hilary Mantel, *Wolf Hall* (2009).", "Sarah Waters, *Fingersmith* (2002).", "Marguerite Yourcenar, *Memoirs of Hadrian* (1951)."],
      s:["Worldbuilding", "Archaism and period flavor", "Postmodernism", "Family saga"] },
    { n:"Crime fiction", a:"Detective fiction · mystery · whodunit · police procedural",
      d:"Narrative organized around a crime and its investigation. The classic puzzle (the whodunit of the Golden Age) invites readers to identify the culprit; the hard-boiled tradition cares about violence, the city and corruption; the police procedural about method; the psychological thriller about the minds of criminal and victim.",
      u:"Plan the crime from the end backwards: what happened, who knew, what clues were left. Distribute true and false clues fairly (the reader should be able to guess). Ronald Knox’s and S. S. Van Dine’s “rules” of fair play (1928–29) are still a useful checklist.",
      c:"The solution must be prepared in the text; a culprit who appears at the end without clues is cheating. Flawless detectives are dull.",
      x:["Edgar Allan Poe, “The Murders in the Rue Morgue” (1841).", "Wilkie Collins, *The Moonstone* (1868); Arthur Conan Doyle’s Sherlock Holmes.", "Agatha Christie, *Murder on the Orient Express* (1934).", "Raymond Chandler, *The Big Sleep* (1939); Tana French, *In the Woods* (2007)."],
      t:"Use one Story Arc for the real chronology of the crime and another for the investigation: chronological order and narrative order show what the reader knows at each moment.",
      s:["Hard-boiled style", "Red herring", "Setup and payoff", "Suspense and surprise", "Dramatic question", "Thriller"] },
    { n:"The fantastic", a:"The fantastic, the uncanny and the marvelous (Todorov)",
      d:"Narrative in which the supernatural or the impossible breaks into a recognizable world. Tzvetan Todorov (*The Fantastic*, 1970) distinguished the fantastic proper (hesitation between a natural and a supernatural explanation), the uncanny (everything is explained) and the marvelous (the supernatural is accepted without surprise, as in fairy tales and fantasy).",
      u:"Decide your book’s regime: should readers hesitate (fantastic), accept new rules (marvelous, epic fantasy) or get an explanation at the end (uncanny)? Once established, the rules of the impossible must not be broken.",
      c:"A rushed final explanation undoes the fantastic effect; and a supernatural that changes nothing in the characters’ lives is just decoration.",
      x:["E. T. A. Hoffmann, “The Sandman” (1816).", "Henry James, *The Turn of the Screw* (1898): ghosts or the governess’s mind?", "Franz Kafka, *The Metamorphosis* (1915).", "Shirley Jackson, *The Haunting of Hill House* (1959)."],
      s:["Magical realism", "Fantasy", "Gothic mode", "Verisimilitude", "Horror"] },
    { n:"Fantasy", a:"Epic / high fantasy · urban fantasy · sword and sorcery",
      d:"Fiction set in invented worlds — or in our world with hidden magic — where the supernatural is an accepted part of reality. High or epic fantasy builds secondary worlds with their own history and stakes; urban fantasy hides magic in contemporary cities; sword and sorcery favors personal adventure; grimdark, moral bleakness.",
      u:"Ground the marvelous in the concrete: food, money, weather, the price of magic. Give the world a history that the characters feel in their daily lives, and limits that make the climax costly.",
      c:"Magic without limits removes tension: if anything is possible, nothing is at stake. Beware the Tolkien imitation — farm boy, dark lord, chosen one — unless you are doing something new with it, and prologues full of invented names.",
      x:["J. R. R. Tolkien, *The Lord of the Rings* (1954–55).", "Ursula K. Le Guin, *A Wizard of Earthsea* (1968).", "Terry Pratchett, the *Discworld* series; Susanna Clarke, *Jonathan Strange & Mr. Norrell* (2004).", "N. K. Jemisin, *The Fifth Season* (2015)."],
      s:["Worldbuilding", "The fantastic", "Hero’s journey", "Exposition and incluing", "Chivalric romance"] },
    { n:"Science fiction and dystopia", a:"Speculative fiction",
      d:"Narratives that start from a scientific, technological or social hypothesis to imagine another world, often in the future. Dystopia imagines an oppressive society that exaggerates present trends; utopia, an ideal one.",
      u:"Start from a “what if…?” and follow its consequences rigorously: economy, politics, language, domestic life. The best science fiction speaks about the present through the future.",
      c:"Exposition dumped in blocks (“As you know, since the Great War…”) is the commonest defect. Show the world through the characters.",
      x:["H. G. Wells, *The Time Machine* (1895).", "George Orwell, *Nineteen Eighty-Four* (1949); Aldous Huxley, *Brave New World* (1932).", "Ursula K. Le Guin, *The Dispossessed* (1974); Margaret Atwood, *The Handmaid’s Tale* (1985).", "Kazuo Ishiguro, *Never Let Me Go* (2005)."],
      s:["Worldbuilding", "Exposition and incluing", "Defamiliarization", "Premise and logline"] },
    { n:"Horror", a:"Supernatural and psychological horror",
      d:"Fiction designed to produce fear, dread and disgust. It ranges from supernatural horror (ghosts, demons, cosmic entities) to psychological horror (the monster inside) and body horror. It descends from the Gothic novel and the ghost story.",
      u:"Dread works better than shock: build it with the ordinary turned slightly wrong, with what is half-seen and withheld, and with characters the reader cares about. The monster is scariest before it is fully shown. Horror is often about something real — grief, guilt, abuse — wearing a mask.",
      c:"Gore without dread numbs; characters who act stupidly so the plot can happen break the reader’s identification. Over-explaining the monster kills it.",
      x:["Bram Stoker, *Dracula* (1897).", "H. P. Lovecraft, “The Call of Cthulhu” (1928), cosmic horror.", "Shirley Jackson, *The Haunting of Hill House* (1959); Stephen King, *The Shining* (1977).", "Toni Morrison, *Beloved* (1987), a ghost story about slavery."],
      s:["Gothic mode", "Suspense and surprise", "Atmosphere", "The fantastic"] },
    { n:"Thriller", a:"Suspense · spy · techno and legal thrillers",
      d:"Fiction built on suspense, danger and pace: the protagonist must prevent something terrible, usually against the clock and against a stronger opponent. Subgenres include spy, political, legal, medical, techno- and psychological thrillers.",
      u:"Establish the threat early and make it personal; give the antagonist intelligence; keep raising the stakes; use short chapters, crosscutting and a ticking clock. The genre’s obligatory scene is the hero at the mercy of the villain.",
      c:"Pace is not the same as tension: explosions with nothing at stake bore. Implausible coincidences and characters who withhold information without reason break the reader’s trust.",
      x:["John Buchan, *The Thirty-Nine Steps* (1915).", "John le Carré, *The Spy Who Came in from the Cold* (1963).", "Thomas Harris, *The Silence of the Lambs* (1988); Gillian Flynn, *Gone Girl* (2012)."],
      s:["Ticking clock", "Suspense and surprise", "Short chapters and cliffhangers", "Crime fiction", "Fichtean curve"] },
    { n:"Romance novel", a:"Love story with an emotionally satisfying ending",
      d:"Genre fiction centerd on a love relationship, whose defining convention is an optimistic ending (HEA, “happily ever after,” or HFN, “happy for now”). It is one of the best-selling genres in English, with many subgenres: historical (Regency), contemporary, romantic suspense, paranormal, romantasy.",
      u:"The relationship is the plot: each scene should move the couple closer or push them apart. Give both leads a strong internal reason to resist the relationship, not just a misunderstanding. Readers expect the obligatory beats — the meeting, the growing bond, the break-up, the grand gesture — done freshly.",
      c:"Conflicts that one honest conversation could solve feel artificial. A love story with an unhappy ending is not, in genre terms, a romance — and readers will feel cheated.",
      x:["Jane Austen, *Pride and Prejudice* (1813), the ancestor.", "Georgette Heyer, *Frederica* (1965), the Regency model.", "Nora Roberts; Beverly Jenkins; Emily Henry, *Beach Read* (2020)."],
      s:["Novel of manners", "Want and need", "Literary and genre fiction", "Five commandments of storytelling"] },
    { n:"Western", a:"The frontier story",
      d:"Fiction set on the American frontier, typically in the second half of the 19th century: lawmen and outlaws, settlers and Native nations, cattle drives, mining towns, a code of honor under the open sky. The revisionist Western questions its myths of conquest and masculinity.",
      u:"The genre offers clear moral confrontations in a vast landscape — useful for stories of law versus justice, community versus individual. Its structure (the stranger who rides into town) adapts to any setting.",
      c:"Native characters as faceless enemies or noble savages, and a romanticized picture of conquest, are the genre’s long-standing faults; serious research is essential.",
      x:["Owen Wister, *The Virginian* (1902).", "Charles Portis, *True Grit* (1968).", "Larry McMurtry, *Lonesome Dove* (1985); Cormac McCarthy, *Blood Meridian* (1985)."],
      s:["Antihero", "Historical novel", "Archetype"] },
    { n:"Novel of manners", a:"Social comedy · portrait of a society",
      d:"A novel that portrays the habits, values, hypocrisies and conflicts of a social world — a town, a class, an era — often with irony.",
      u:"The milieu is a character: parties, dinners, drawing-room conversations, rituals. The narrator’s irony reveals the gap between what characters say and what they do.",
      c:"Satire of manners ages with the manners; what remains are the characters. Do not let the social portrait swallow the story.",
      x:["Jane Austen, *Pride and Prejudice* (1813) and *Emma* (1815).", "Edith Wharton, *The Age of Innocence* (1920).", "Eça de Queirós, *The Maias* (1888), subtitled “Episodes of Romantic Life.”"],
      s:["Satire", "Irony", "Realism and naturalism", "Ironic style"] },
    { n:"Psychological novel", a:"Novel of introspection",
      d:"A novel centerd on the characters’ inner lives — motives, conflicts, memories, consciousness — more than on external action.",
      u:"Close focalization, interior monologue, free indirect discourse, memory flashbacks. Action can be minimal; tension comes from the contradiction between what the character feels, thinks and does.",
      c:"Without a concrete conflict that forces a choice, introspection turns into rumination. Give the character an event that tests them.",
      x:["Fyodor Dostoevsky, *Crime and Punishment* (1866).", "Henry James, *The Portrait of a Lady* (1881).", "Virginia Woolf, *Mrs Dalloway* (1925); Patricia Highsmith, *The Talented Mr. Ripley* (1955)."],
      s:["Interior monologue", "Free indirect speech", "Existentialism", "Modernism"] },
    { n:"Picaresque novel", a:"The rogue who lives by his wits",
      d:"A narrative, usually in the first person, about a *pícaro* — a crafty outsider who passes through many masters and places — that shows society from the bottom up, with humor and cruelty. Born in 16th-century Spain, it took root in English with Defoe, Fielding and Smollett.",
      u:"An episodic structure (each master, each city, one episode) and a cynical, entertaining voice. Good for social satire and unreliable narrators.",
      c:"Loose episodes need a thread: a change in the narrator, or a question that runs through the book.",
      x:["*Lazarillo de Tormes* (1554), anonymous.", "Daniel Defoe, *Moll Flanders* (1722); Henry Fielding, *Tom Jones* (1749).", "Mark Twain, *Adventures of Huckleberry Finn* (1884); Saul Bellow, *The Adventures of Augie March* (1953)."],
      s:["Antihero", "Unreliable narrator", "Satire", "Mosaic novel"] },
    { n:"Travel writing", a:"Travel narrative · road novel",
      d:"Narratives organized around a journey — real or invented — in which the outer journey accompanies an inner transformation. The tradition runs from medieval travelers’ tales through the Grand Tour to the modern road novel.",
      u:"Structure comes from the itinerary; interest comes from the gaze. Alternate landscape, encounters and reflection. The road or the sea gives a natural rhythm of episodes.",
      c:"A catalog of places does not make a narrative: it needs a question and a traveler who changes.",
      x:["Laurence Sterne, *A Sentimental Journey* (1768).", "Mark Twain, *The Innocents Abroad* (1869).", "Bruce Chatwin, *In Patagonia* (1977); Jack Kerouac, *On the Road* (1957).", "Fernão Mendes Pinto, *The Travels* (*Peregrinação*, 1614)."],
      s:["Hero’s journey", "Bildungsroman", "Frame narrative", "Beat Generation"] },
    { n:"Chivalric romance", a:"Arthurian romance · the Matter of Britain",
      d:"Medieval and Renaissance narratives of knights, quests, ordeals, courtly love and Christian marvels. In English: *Sir Gawain and the Green Knight* (late 14th century) and Malory’s *Le Morte d’Arthur* (printed by Caxton, 1485); on the Continent, Chrétien de Troyes and *Amadis of Gaul*.",
      u:"A source for fantasy, medieval historical fiction and parody. The quest structure (a search with successive ordeals) still organizes many plots, and its interlaced threads anticipate the modern multi-strand novel.",
      c:"The genre’s values (honor, lineage, chastity) are not ours: use them knowingly, or to question them.",
      x:["*Sir Gawain and the Green Knight*.", "Thomas Malory, *Le Morte d’Arthur* (1485).", "T. H. White, *The Once and Future King* (1958), a modern retelling.", "Cervantes, *Don Quixote*, its great parody."],
      s:["Hero’s journey", "Fantasy", "Interlacing"] },
    { n:"Folk tale and fable", a:"Fairy tale · folk tale · fable · legend",
      d:"Narratives from oral tradition, collected and fixed in writing: wonder tales, animal tales, local legends, fables with a moral. In English, collected by Joseph Jacobs (*English Fairy Tales*, 1890) and Andrew Lang’s colored *Fairy Books*; in Germany, by the Brothers Grimm.",
      u:"Simple, powerful structures (three trials, the broken prohibition, the youngest son), stock characters and a rhythm of repetition. Retell them, update them, or use them as the skeleton of a novel. Vladimir Propp’s *Morphology of the Folktale* (1928) catalogs their 31 functions.",
      c:"An explicit moral at the end of a story for adults sounds like a sermon. The versions collected in the 19th century are often cruel and strange — that is where their power lies.",
      x:["Aesop; La Fontaine, *Fables* (1668–1694).", "The Brothers Grimm, *Children’s and Household Tales* (1812).", "Angela Carter, *The Bloody Chamber* (1979), fairy tales rewritten for adults."],
      s:["Stock character", "Rule of three", "The seven basic plots", "Allegory"] },
    { n:"Family saga", a:"Generational novel · dynasty novel",
      d:"A novel or series that follows a family over several generations, tying private lives to historical change: fortunes made and lost, inheritances, feuds, secrets passed down.",
      u:"Choose a house, a business or an object to anchor the generations. Echo situations from one generation to the next (the same mistake, the same name), and decide carefully when to skip time. A family tree and a timeline are essential.",
      c:"Too many characters with similar names, and time jumps that leave readers lost; each generation needs its own dramatic question, not just a summary.",
      x:["John Galsworthy, *The Forsyte Saga* (1906–21).", "Thomas Mann, *Buddenbrooks* (1901).", "Gabriel García Márquez, *One Hundred Years of Solitude* (1967); Min Jin Lee, *Pachinko* (2017)."],
      t:"A Story Arc per generation, with Branches where a line splits off, keeps the saga readable on the board.",
      s:["Historical novel", "Time skip", "Interlacing", "Series bible"] },
    { n:"Young adult fiction", a:"YA · teen fiction · middle grade for younger readers",
      d:"Fiction written for and marketed to readers of roughly 12 to 18, usually with teenage protagonists, a close first-person or third-person voice and themes of identity, first experiences and independence. Middle grade addresses roughly 8 to 12.",
      u:"Authenticity of voice is everything: write the protagonist’s present, not an adult’s nostalgia. Teenage characters must solve their own problems; adults step aside. YA can tackle any subject — grief, violence, sexuality — if it is honest.",
      c:"Condescension and moralizing are fatal; so is slang that will date in a year. Protagonists who act like thirty-year-olds miss the readership.",
      x:["S. E. Hinton, *The Outsiders* (1967).", "Suzanne Collins, *The Hunger Games* (2008).", "Angie Thomas, *The Hate U Give* (2017)."],
      s:["Bildungsroman", "First person — protagonist", "Literary and genre fiction"] },
    { n:"Literary and genre fiction", a:"Commercial fiction · upmarket · genre conventions",
      d:"A publishing distinction more than a literary one. Genre fiction (crime, romance, fantasy, science fiction, horror, thriller) is defined by conventions and promises readers expect to see fulfilled; literary fiction is marketed on voice, style and depth of character. “Upmarket” or “book-club” fiction sits in between.",
      u:"Know which shelf you are writing for and its obligatory elements; then surprise within them. Many classics are genre books (*Frankenstein*, *The Moonstone*), and many literary novels borrow genre engines (Ishiguro, McCarthy, Atwood).",
      c:"Snobbery in either direction is a mistake: genre is not inferior, and literary is not an excuse for having no plot. Breaking a genre’s core promise (no solution in a mystery, no happy end in a romance) alienates its readers.",
      x:["Genre-bending literary novels: Kazuo Ishiguro, *Never Let Me Go*; Cormac McCarthy, *The Road*; Colson Whitehead, *The Underground Railroad*."],
      s:["Five commandments of storytelling", "Crime fiction", "Romance novel", "Fantasy"] }
  ]},

  { name:"Ways of writing prose", items:[
    { n:"Plain style", a:"Classic prose · transparency · “prose like a windowpane” (Orwell)",
      d:"Clear, precise, unobtrusive prose that does not draw attention to itself: readers see the story through it, as through a clean window. Orwell’s essay “Politics and the English Language” (1946) is its best-known manifesto.",
      u:"Well-built sentences, exact vocabulary, adjectives chosen one by one, rare and accurate metaphors. It is the most versatile register and the one that ages best.",
      c:"Plain does not mean poor or neutral: precision takes work. Without a single strong image, the text turns gray.",
      x:["Anton Chekhov’s stories; J. M. Coetzee, *Disgrace* (1999).", "George Orwell, *Animal Farm* (1945).", "Kazuo Ishiguro, *Never Let Me Go* (2005)."],
      s:["Minimalism", "Diction", "Lyrical style"] },
    { n:"Lyrical style", a:"Poetic prose in narrative",
      d:"Prose that approaches poetry: marked rhythm, imagery, repetition, musicality, attention to sensation and states of mind.",
      u:"Good for memory, landscape, childhood, loss, and for narrators sensitive to the world. Alternate with plainer passages so the lyricism keeps its effect.",
      c:"A whole novel in a lyrical register can tire the reader and smother the action. Emotion should arise from images, not adjectives — or it becomes purple prose.",
      x:["Virginia Woolf, *The Waves* (1931).", "Dylan Thomas, *Under Milk Wood* (1954), a “play for voices.”", "Michael Ondaatje, *The English Patient* (1992); Marilynne Robinson, *Housekeeping* (1980)."],
      s:["Poetic prose", "Sentence rhythm", "Sensory imagery", "Aestheticism and Decadence", "Purple prose"] },
    { n:"Purple prose", a:"Overwritten prose · “purple patch” (Horace)",
      d:"Prose so ornate, emotional or adjective-laden that it draws attention to itself and away from the story. The phrase comes from Horace’s *purpureus pannus*, a purple patch sewn onto a plain garment. Its opposite failure is beige prose, so flat it gives nothing.",
      u:"Recognize it in revision: stacked adjectives and adverbs, elaborate synonyms for simple words (“orbs” for eyes), metaphors piled on metaphors, emotion described rather than evoked. Keep the single strongest image and cut the rest.",
      c:"Not every rich style is purple: Nabokov and Dickens are lavish but precise. The test is whether each flourish adds meaning or only noise.",
      x:["Edward Bulwer-Lytton’s “It was a dark and stormy night…” (*Paul Clifford*, 1830), which inspired a contest for the worst opening sentence.", "Purple: “Her cerulean orbs sparkled like twin sapphires drowning in a tempestuous sea of tears.” / Revised: “Her eyes filled.”"],
      s:["Plain style", "Lyrical style", "Kill your darlings", "Cliché"] },
    { n:"Telegraphic style", a:"Verbless sentences · fragments",
      d:"Prose made of very short sentences, often without verbs, dropping articles and connectives. It imitates note-taking, urgency, thought in flashes.",
      u:"Useful in scenes of extreme tension, diaries, a character’s notes, the mind of someone in shock. In small doses, it brings speed.",
      c:"For pages on end, it tires the reader and reads like a script or a list. Use it as a change of rhythm.",
      x:["“Siren. Smoke. Nobody on the stairs. The phone, again.”", "Mr. Jingle’s chatter in Dickens’s *The Pickwick Papers*: “Heads, heads — take care of your heads!”"],
      s:["Short sentences", "Ellipsis", "Asyndeton"] },
    { n:"Cinematic style", a:"Writing in shots",
      d:"Prose that imitates the camera: it describes what can be seen and heard, shot by shot (wide, medium, close-up), with hard cuts between scenes, little commentary and often in the present tense.",
      u:"Very effective in action and suspense. Think in shots: open wide, move in to the revealing detail, cut. The tool’s Narrative board, with its Scenes, helps you assemble the book like an editing table.",
      c:"A book is not a film: prose can enter characters’ heads, which the camera cannot. Giving that up wastes what only the novel can do.",
      x:["An opening in shots: “The empty beach. A red towel. Beside it, a child’s shoe.”", "Dashiell Hammett, *The Maltese Falcon* (1930): almost no access to Spade’s thoughts."],
      s:["Third person objective", "Crosscutting", "Show, don’t tell", "Late in, early out"] },
    { n:"Reportage style", a:"Literary journalism · narrative nonfiction · New Journalism",
      d:"Prose that uses the techniques of the novel to tell true events, or fiction that imitates reportage (dates, names, documents, testimony). Truman Capote’s *In Cold Blood* (1966) and the American New Journalism of Tom Wolfe and Joan Didion are the landmarks.",
      u:"It brings plausibility and urgency. In fiction, simulated reportage (interviews, transcripts, news items) creates a documentary effect.",
      c:"In nonfiction, inventing breaks the pact with the reader. In fiction, fake reportage needs total consistency of detail.",
      x:["Truman Capote, *In Cold Blood* (1966).", "Svetlana Alexievich, *The Unwomanly Face of War* (1985).", "Fiction: Taylor Jenkins Reid, *Daisy Jones & The Six* (2019), told as an oral history."],
      s:["Epistolary", "Verisimilitude", "Telling detail", "Social realism"] },
    { n:"Essayistic style", a:"The novel that thinks",
      d:"Narrative in which the narrator (or the author) interrupts the story to reflect — on life, society, writing itself — bringing the novel close to the essay.",
      u:"It works when the reflection grows out of the story and illuminates it. A narrator thinking aloud can be the book’s great character.",
      c:"Digressions stall the plot: ration them, and make sure each adds something the scene could not say.",
      x:["Milan Kundera, *The Unbearable Lightness of Being* (1984).", "George Eliot, *Middlemarch*: the narrator’s reflections on the “roar which lies on the other side of silence.”", "W. G. Sebald, *The Rings of Saturn* (1995)."],
      s:["Intrusive narrator", "Existentialism", "Metafiction", "Descriptive pause and digression"] },
    { n:"Ironic style", a:"Distance and double meaning",
      d:"Prose in which the narrator says one thing and lets us see another: praise that is criticism, seriousness that is mockery. Irony creates complicity with the reader.",
      u:"Irony lives in the gap between tone and content, between what characters think of themselves and what readers see. Austen’s free indirect discourse is the classic English school.",
      c:"Constant irony empties the characters and stops readers from caring about them. Know when to put it aside.",
      x:["Jane Austen’s opening of *Pride and Prejudice*: a “truth universally acknowledged” that is nothing of the kind.", "Evelyn Waugh, *Scoop* (1938); Muriel Spark, *The Prime of Miss Jean Brodie* (1961).", "Machado de Assis, *The Posthumous Memoirs of Brás Cubas* (1881)."],
      s:["Irony", "Satire", "Novel of manners", "Intrusive narrator", "Free indirect speech"] }
  ]}
  ]});
